// The gallery's block texts in English (spec 2026-10-23 languages-b §9): display name, description and notes of every id HANDLES points at.
// Block ids, parameter names, cut.ts code and English technical terms stay as they are. blocks.test.ts checks every id has one.
import type { BlockText } from './blocks.ts';

export const BLOCKS_EN: Record<string, BlockText> = {
  'core.flash': { label: 'Flash', doc: 'Flashes a color over the whole frame (white by default); retakes, transitions, a camera shutter; fade out is the ending fade: over the whole length of the item the colour slowly covers the frame (color #000 fades to black), fade in fades in from the colour at the start; keys \"second:opacity\" follows keyframes (fade to black, fade from white, a double flash); mode picks the shape of the light; blend changes the blend mode (screen only brightens).' },
  'core.title': { label: 'Title', doc: 'The old title block, kept so older projects open; new films use the Title block (common.heading) and its templates.' },
  'core.caption': { label: 'Caption', doc: 'The old caption block, kept so older projects open; new films use the shared caption block (common.caption) and its templates.' },
  'core.lowerThird': { label: 'Lower third', doc: 'A main line plus subtitle with a color bar at the lower left; places, names, times.' },
  'core.endCard': { label: 'End card', doc: 'Several lines of text appearing one by one at the end (one entry per line); thanks, credits, dates.' },
  'common.backdrop': { label: 'Backdrop pattern', doc: 'A patterned background for the whole film, placed under the video; it is the ground that shows when the video shrinks into a panel, with colors taken from the theme. glow lets a patch of light show through at the bottom, its strength following "seconds:strength" (getting hotter with the score or the mood); bits scatters a few small confetti bits down both sides (dots, four-point sparkles, zigzags, crosses in the theme\'s colours, twinkling), on any pattern.' },
  'common.ambient': { label: 'Shifting ambient background', doc: 'The background color of the whole film shifts along a series of colors with a "level" (deeper the further you dive, darker as it gets later, bluer as it gets colder), with drifting particles and fading light beams; placed under the video, and its value is shared with common.meter. look sky is the sky of a day: the level is the mood (0 dawn, 1 storm, 2 clearing, 3 golden hour, 4 dusk, 5 night) with drifting clouds, thin rain in the storm, sun as it clears, string-light glow at dusk, stars at night, and lightning at the flash times (the weather of a birthday, a wedding, a day in a vlog; thunder: common.thunder).' },
  'common.shader': { label: 'Animated background (GPU)', doc: 'A flowing textured background for the whole film, drawn live on the GPU; colors default to the theme; placed under the video (openers, end cards, sections without footage, behind panels).' },
  'common.panel': { label: 'Video panel frame', doc: 'The frame around a video shrunk into a rectangle. x, y, w, h must equal the video\'s frame and radius must equal the video\'s corner radius; place it above the video track.' },
  'common.badge': { label: 'Number badge', doc: 'A number (No.1, 02) inside a badge, optionally followed by a shop-name or title plate (plate); rankings, lists, section intros (which shop, which tip).' },
  'common.tag': { label: 'Pill tags', doc: 'Small tags, comma separated in tags, appearing one after another: short words under a title, a place, a date, a shop name.' },
  'common.burst': { label: 'Burst card', doc: 'A card where one big word bursts out. A 【word】 in brackets turns accent-colored; common.speedlines can be added behind it.' },
  'common.speedlines': { label: 'Speed lines', doc: 'Comic speed lines, put behind a burst card or at a moment of surprise, a dash or a turn; look changes them: radiating from one point, concentration lines closing in from every edge, or parallel streaks flying across the frame.' },
  'common.caption': { label: 'Caption (shared)', doc: 'A caption whose look (style), word effect (wordFx), entrance, exit, colours and font go together freely; the usual combinations are named caption templates (npm run tellcut -- catalog CAP lists them; template takes an id, c.captionTemplate sets a whole film\'s). words are the speech\'s word times (speechCaptions with karaoke gives them); without them a word effect is spread evenly by length. 【word】 is highlighted, {word} bleeped into symbols; name and speaker show who speaks (speaker 1 = the theme\'s accent2, 2 = the highlight colour, 3 = the main colour; with tint off only the name chip changes colour; role is a small title beside the name); point puts the name in a chip at the left with an arrow toward the speaker; gloss is a smaller translation underneath; tag a chip in the main colour above; y pins the lower edge at any height; big defaults to handwriting, qa to a serif, neon to a rounded face, replaced by styleFont or the item\'s own font; it keeps clear of short-video interfaces at the bottom and sides.' },
  'common.slam': { label: 'Slam text', doc: 'One line of huge text "slammed" onto the frame (zooms in with a bounce, a slight shake, tilted); a 【word】 turns accent-colored (hlScale enlarges it). stagger slams each line down in turn; a small line can go above or below (kicker / after); enter: press shrinks from large like ink bleeding, chars bounces up one character at a time; bar wipes an accent-colored bar open under the text, drift enlarges very slowly once settled (a beat card); kickerBg puts the small top line in a color block that slides in from the left, shade darkens the area behind the text. For key lines, exclamations, hooks and conclusions.' },
  'common.censor': { label: 'Bleep sticker', doc: 'A censor sticker over the mouth (pops in, then sways left and right); used when a word can\'t be said, together with the common.beep bleep; move it with the item\'s transform.' },
  'common.stamp': { label: 'Stamp', doc: 'A stamp or a card "stamped" onto the frame; verdicts such as verified, key point, recommended, done, NG; goes with common.thud. head adds a small widely spaced line above the word (VERDICT; on box, circle, double and ember).' },
  'common.pen': { label: 'Hand-drawn marks', doc: 'Marks that appear as if drawn with a pen, stroke by stroke, in the box x, y, w, h; kind picks what is drawn. style changes the pen: smooth clean lines (default), ballpoint, marker, crayon (fills are diagonal strokes with paper texture), pencil; boil makes the line re-wobble several times per second (a hand-drawn animation feel). Points out key spots, products and details in the frame; picture books, notebooks, tutorials.' },
  'common.sparkle': { label: 'Sparkle stars', doc: 'Sparkle marks: four-pointed stars bursting or twinkling, coloured paper falling, a cross flare glinting; celebration, surprise, emphasis, a premium feel.' },
  'common.emoji': { label: 'Emoji sticker', doc: 'A big emoji (char): a sticker, a rain, rising reactions, a double-tap heart, or a cover over a face; emotion, punchlines, celebration, foodie vibes, likes. In float and tap, ♥ is drawn as a pink heart.' },
  'common.header': { label: 'Chapter label', doc: 'A chapter label: shows where you are in tutorials, lists and section intros. shade lays a dark gradient over the top of the frame (shadeH high) so the small text reads on bright footage.' },
  'common.glitch': { label: 'Glitch', doc: 'Digital interference in bursts (the seed decides when); transitions, scares, a techy feel, the "something went wrong" moment. shift sets how far things move. rgb, block and the scan jump show in the preview only in a Chromium browser (Chrome, Edge); the export always uses Chrome.' },
  'common.progress': { label: 'Progress bar', doc: 'Shows how far the film has got, as a progress bar or chapter marks; common in hook shorts, tutorials, recipes and travel diaries. The ten modes runner, stretch, paws, segments, fuse, battery, rocket, ring, vine and stamps go along the same way: step -1 runs the whole way with the film and arrives up to 1 s before the item ends, leaving time for the arrival; step 0 and up is the current chapter, travelled from its start to its end within this item, one item a chapter, dots the number of chapters. paws and segments are thin enough for the top edge; runner, stretch, fuse, battery and vine are taller: put them at the bottom (position bottom), or give common.header its own y to make room at the top.' },
  'common.meter': { label: 'Value meter', doc: 'A big number that jumps over time to each value (depth, altitude, temperature, a count, a rank…); in films whose spine is "more and more…", it makes the progress visible. A number in the third part of a stop is that stop\'s own count time (shared with ambient).' },
  'common.scoreboard': { label: 'Score ticket', doc: 'A ticket card at the top: a title row plus several cells (icon, name, value), one state per section; the cell that changes bounces and can carry a small note; records, catches, collection progress, rating cards (taste ★★★★).' },
  'common.receipt': { label: 'Receipt', doc: 'A thermal receipt: each line "second|icon|name|amount|tone" prints when its time comes (the paper grows downward, older lines scroll up), then a total prints last (【word】 turns red); tone bar is a white-on-black shop-name strip. Spending, travel expenses, unboxings, "what it cost vs what it got".' },
  'common.tripclock': { label: 'Trip clock', doc: 'The local time at the top of the frame (running forward with the shooting time), how long since arrival, and a route lighting up stop by stop; travel, one-day itineraries, films that follow the clock.' },
  'common.route': { label: 'Hand-drawn route map', doc: 'A hand-drawn route map on a beige paper card: a row of big-number promises at the top (number|caption), pencil streets below, and a red dashed line drawn from the start (a big clock or emoji) lighting up stop by stop, the last few stops can get question marks; upto draws only up to stop k and already starts it lit up to a stop (already k−1 with upto k: the card comes back for a beat to light the next stop), nameSize sets the size of the stop names; shop hunts, one-day tours, walking routes, series teasers. look page is a whole-page notebook route map: the places sit in a loop (or where pts puts them), the whole way is pencilled in faintly, a blue ballpoint dashed line is drawn leg by leg with the pen riding its tip, the walking time is written in red beside each leg (legs) with a wavy underline, each place turns into a doodle (icons: bowl / bun / box / jar / tofu / cup / station / train / house / star or an emoji) and a red tick as it is reached, its name hand-written on a highlighter swipe; the camera moves by cams "seconds|mode" between full (the whole map), walk (the map up top, room for the footage below), stop (shrunk to a scrap of paper in the corner, the current place pulsing), end and near (close in, following the current place); loop draws the way back to the start, flash makes every tick pop in turn; put it over common.paper look grid.' },
  'common.card': { label: 'Index card', doc: 'The top card of a stack of index cards: the upper half is a picture window (it can hold any block, such as the project\'s own illustration fx, or one big emoji), the lower half on ruled lines holds the step number, title, quantity (highlighter) and a small tip; turn the page to change step, cards can be dealt in and slide out at the end; recipes, tutorial steps, lists.' },
  'common.countdown': { label: 'Countdown', doc: 'A big number counting down from from to to (split evenly over the item); the last tick can be replaced by a word (GO!); quizzes, challenges, guessing games, ranking reveals.' },
  'common.list': { label: 'List card', doc: 'A card with a title and several items appearing line by line; style changes the mark in front of each line; reviews, tutorials, three key points, myth-busting. look: stack has no card: big text slams in one line per beat, numbered color blocks, the newest line in highlighter color (keeps each photo\'s name during a burst of photos).' },
  'common.rating': { label: 'Rating card', doc: 'A rating card: several rows of "item:score" (stars can be half, or bars), the scores growing row by row, with an optional big total; food, unboxing, film and TV reviews.' },
  'common.info': { label: 'Info card', doc: 'A theme-styled info card: a title row plus several rows of "icon text" (📍 address, 🕐 opening hours, 💰 price, 🚇 transit...), sliding up from the bottom safe zone (or down from the top); travel, food, outfits, shop intros.' },
  'common.polaroid': { label: 'Freeze-frame Polaroid', doc: 'Freezes one moment of the footage into a Polaroid: a white flash first, then the photo drops in at an angle with one handwritten line below; crop { x, y, zoom } (or "x,y,zoom", as the other photo cards and shot lines write it) frames the still in the square photo like a clip\'s crop (keep burned-in text out, aim at a face); the line below is in the theme\'s display font, not handwriting, unless font is set (for example LXGW WenKai TC); highlights, travel, best moments (c.polaroid automatically takes source and time from the clip that is playing, and adds a shutter sound; not its crop, give that yourself).' },
  'common.mystery': { label: 'Question-mark suspense', doc: 'A suspense cover: the edges of the frame darken, a main-color round seal with a question mark spins in at the center, one line above ("The 5th shop is...") and an optional hint below, with text on two taped-on paper-tape strips scrolling slowly; teasers that hold back the answer for the original film.' },
  'common.outro': { label: 'End funnel', doc: 'An end card, look picking the funnel card (cta), the thank-you credits (credits) or a show\'s end card (episode); the big words go in lines, one per line (on the funnel card 【word】 goes into a small main-color tag), and cta and credits bring in one line a beat (beat is a beat in seconds).' },
  'common.film': { label: 'Film texture', doc: 'A film texture over the whole frame (one block); the grain changes every frame and is blended into the picture (most visible in the shadows and mid-tones, none in pure black or clipped white); laid on the top layer when you want a film, nostalgic, textured feel; grain 0.07–0.15 is a light film look, 0.3 and up coarse; blend overlay is stronger contrast, mostly in the mid-tones (brand films, a cinematic look, grain about 0.07).' },
  'common.tone': { label: 'Color tone', doc: 'Color grading for the whole film: a soft-light layer over the video with colored light in the middle and darkened edges; warm by default (street food, sunsets, nostalgia), blue makes it cool; often used with common.film.' },
  'common.paper': { label: 'Paper desktop', doc: 'A paper ground for the whole film; static, placed under the video; planners, recipes, handwritten tutorials, picture books, notebooks; goes with common.notecard (with card: false it writes on this card).' },
  'common.notecard': { label: 'Handwritten index card', doc: 'A ruled index card whose content is handwritten stroke by stroke, mode picking the page; recipes, tutorials, planner style; with card off it writes on the card drawn by common.paper.' },
  'common.handwrite': { label: 'Handwriting', doc: 'Handwriting written stroke by stroke, each sentence with its own time: "second-second|sentence" gives handwritten captions written out character by character on the narration\'s timing (replace: one sentence at a time; a sentence with an end time starts fading hold seconds after it, 1.2 by default, or when the next one starts), accumulating line by line like writing a letter (stack), or a small note stuck on a photo (paper: note, with one line of small text); look picks the pen (fountain pen, chalk, highlighter, crayon); words listed in red are written in red pen and get an underline drawn beneath them when reached; postcards, diaries, planners, recipes.' },
  'common.gauge': { label: 'Gauge meter', doc: 'A half-circle speedometer: color zones (start:name) along the scale band, a spring needle, an LED digit readout and the current zone name, with a halo gradually turning into devil horns; each hit "second:points" makes the needle bounce; it can jitter at the start, sweep once on boot, flash a red alarm and finally max out (the needle slams to the end, the glass cracks); readout shows words in the LED instead of the number (a rank like No.1, a word; comma-separated words change at each hit, {v} = the score). The default look: neutral is a plain gauge (color-only zones, no halo, alarm or blow-up; zones, halo, danger and boom you set still count, so your own zones bring their names); for a guilt index (sin zones from innocent to hellish, halo, alarm, blow-up) use look: guilt, and there give your own zones with halo: false, danger: -1, boom: -1 to leave them out; guilt index, spiciness, crush index, heat, scores, ranks.' },
  'common.hangtag': { label: 'Points hang tag', doc: 'An evidence-tag style stamp stamped across the frame at an angle: a big "+points", a name, small original text and a one-line quip; then the "+points" flies to a chosen point (for example common.gauge) and bursts in a ring there; scoring, prices, calories, offences, collecting.' },
  'common.strike': { label: 'Strike-through rewrite', doc: 'A soft thin line of text floats up first (with a small heading line above), then at second at it is struck out in the accent colour (look picks how) and a big accent-ground word stamp is put underneath; "it was A, actually B", expectation vs reality, myth-busting, reversals.' },
  'common.timelapse': { label: 'Fast-forward clock', doc: 'Time fast-forwarding: the frame darkens, the clock hands spin wildly, the hours below count up ("Chilled 2.3 hours"), and "▶▶ fast forward" flashes at the top; chilling, baking, fermenting, waiting, a jump cut across a night.' },
  'common.routeboard': { label: 'Route board', doc: 'A dark route board at the top: a mini map with real latitude and longitude (city dots, the walked line lighting up), the current stop flashing, the stop count 01/03 flipping like cards, and the date; stops "second|city|date" decides which stop lights up at each moment (- en route, all everything); hangs over a whole multi-city travel quick-cut; the sights of one city (all within half a degree) are spread over the whole map by themselves.' },
  'common.mapjump': { label: 'Full-screen route jump', doc: 'The whole frame becomes a beige paper route map (real latitude and longitude, graticule lines and degrees) for a beat or two: leg draws a red arc from the previous stop to the next, the dot landing on the beat; all draws the whole route, each stop stamped in turn; a big title above and the date below; changing cities in a travel quick-cut, a full-trip recap.' },
  'common.ticket': { label: 'Arrival ticket', doc: 'A cream-colored ticket slams in below (red ticket head + No.01/03, a big city name, Latin text, a date stub at the right, perforation line), and at second stampAt a red double-ring "Arrived" stamp lands on it; each stop in a travel quick-cut, itineraries, tickets, boarding.' },
  'common.snap': { label: 'Photo flash-in', doc: 'When a photo comes in, a white light flashes, a white photo frame closes in from outside the frame, and an orange glowing camera date stamp sits in a corner (\'22 5 26); by default it frames the whole picture, window [x, y, w, h] (fractions of the frame like a clip\'s frame, for example a 4:5 photo window) puts the frame round that window instead, with the date stamp in its corner; bursts of photos, memories, a film-camera feel.' },
  'common.stations': { label: 'Station stamps ending', doc: 'The last beat of an ending: the lower part of the frame darkens, a red line strings every stop\'s stamp together (a numbered red round stamp, a big station name, Latin text) which are stamped down together, then the date floats up; travel quick-cuts, series recaps, itinerary summaries.' },
  'common.postcard': { label: 'Postcard', doc: 'One stop of a postcard travelogue: a stack of postcards on a wooden table, a new one slides in (or flips over) and lands on top, a corner stamp (that stop\'s picture) and a postmark (place name + date) come down, and the narration is handwritten on the card character by character; when the card has settled the photo window is a transparent hole and the main-track clip (frame = postcardWindow) plays through it, while the window shows a still image when the card moves (the card lies over the clip then); the last card can flip to the back to write on and everything can be spread out, and drop lands the last cards after the spread; from pushAt the window grows to full screen with its clip and from pushBack it shrinks back onto the card (keep the window clip on the main track while it grows and shrinks, a full-screen clip while it is full, so the captions stay on top); simple parameters give one card, card / pile / spread give the whole set.' },
  'common.postmark': { label: 'Postmark', doc: 'A postmark "stamped" onto the frame: a double ring, a place name on the upper arc, the local-language place name on the lower arc, the date in the middle, five wavy lines at the right, uneven ink, optionally with a perforated stamp (the picture is one moment of the footage; if none is given it is a drawn sunset sea); travel, sending letters, "been here", date stamps.' },
  'common.frame': { label: 'Physical frame', doc: 'A moving physical frame with the video playing inside it: a Polaroid, a wooden picture frame, an old TV or a card, dropping or sliding in, able to flip to the back to write on, able to leave; while moving the window shows a still image of the footage, and once settled the window becomes a hole through which the main-track clip (frame = frameWindow(params)) plays; memories, showcasing work, playback on an old TV, a person in a picture frame.' },
  'common.dotmatrix': { label: 'Dot-matrix text', doc: 'Dot-matrix text: any text (Chinese too) is shrunk to a dot matrix and drawn back dot by dot; look led is a black-ground marquee sign (lit dots glow, unlit dots form a grid), print is ink dots on thermal paper; signs, marquees, LED boards, receipts, queue displays.' },
  'common.digits': { label: 'Digit display', doc: 'A digit display: style vfd is the green dot-matrix subtotal of a cash register ("second|+40": the number jumps up, a yellow "+40" flashes out, blinking at the total), led is a red seven-segment queue number ("second|02": the number flashes three times when it changes, with a vertical small plate beside it reading Now serving / Next); add title to make it a signboard (shop name and small text at the left, the display at the right); spending, scoring, queue numbers, countdowns, floors.' },
  'common.printer': { label: 'Receipt printer', doc: 'A thermal receipt printer (at the bottom of the frame): each line "second|style|text|amount" is printed in dot-matrix type with the stepper motor feeding the paper in jerks, the paper growing upward and disappearing behind the clip (the video window); shop is a white-on-black shop-name strip and the print head shows worn streaks; the machine\'s VFD subtotal jumps up automatically and flashes "+40"; at the end a stamp lands, a red pen strikes out a line, and tearAt tears off the whole receipt and spreads it in the middle of the frame; food spending logs, eating and adding up as you go, shopping lists. It looks like a real POS printer: thermal paper with grain, a slight curl, a serrated tear and a shadow, a satin body, a metal tear bar and the VFD behind smoked glass; surface counter lays a lit countertop below clip (the bottom edge of the video window), none when the film has its own background.' },
  'common.rolldoor': { label: 'Roll-down shutter', doc: 'A roll-down shutter: steel slats are pulled down from the top to cover a frame (usually the video window), and once fully down a paper sign (Closed today) pops onto it; dir up starts closed and rolls up open at the given time; closing time, endings, "to be continued"; goes with the common.rattle sound.' },
  'common.callout': { label: 'Circle callout', doc: 'Marks something in the frame and pulls a callout line out to a label; the mark is drawn first, the line pulled out, the label pops up and stays inside the safe zone automatically; points out ingredients, methods and other key points.' },
  'common.slip': { label: 'Number slip', doc: 'A cream number slip: mode stub is a red number stub at the left (reason 01) + a dashed tear line, with a title and small text at the right, printed out from the left (which reason, a key line); mode board is an end number slip: big text, a dashed line, a numbered recap (items) popping in line by line, one line of small text at the bottom, with the background darkened; famous queue shops, three reasons, recap summaries. slot makes the stub shrink and fly, in its last 0.55 s, into that card of a common.progress slots row (slots and slotY must match that item): each rule tucked into its numbered card once it is said.' },
  'common.quote': { label: 'Quote card', doc: "A quote card: a quote (text, line by line), who said it (who) and a line of small text (kicker), the hardest-hitting line (hit, the last line by default) in the main color (accent); mode picks how it appears; quotes from podcasts, interviews, talks and confessions." },
  'common.wipe': {"label":"Diagonal color-band transition","doc":"A transition, mode picking one of nine looks; put the cut point (a layout switch, a scene change) at the exact middle of the item, and place it on the top layer (layer: top); goes with common.whoosh; the slope of band and stripes follows slant (how many frame widths the top and bottom ends are offset, so the angle depends on the frame: 1 is about 30 degrees at 9:16, 45 at 1:1 and about 60 at 16:9); iris, blinds and ink ignore dir."},
  'common.duo': { label: 'Two-person split conversation', doc: 'A split-screen frame for two people (top and bottom with dir v, or left and right with h): a small color-block tag + topic at the head, a caption band between the two panes (below them when side by side), and a name plate at a corner of each pane; segs "start-end|a/b/ab" says who is speaking: the speaking pane lights up (an outline and inner glow in the speaker\'s color, a filled name plate, a jumping volume bar) while the other pane goes gray and dim; the two people\'s clips are put into the two panes with frame set to duoWindow(\'a\'|\'b\', the same parameters) (a\'s with c.clip, b\'s at the same moment with c.beside(a\'s id, { frame: duoWindow(\'b\', the same parameters), crop }): one two-shot cut into its two people, or a second camera); a long topic shrinks, then takes two lines, and is never cut off; size scales the header and name-chip text together; two-person interviews, podcasts, debates, he said she said; goes with common.versus and caption\'s point. mode solo is a podcast clip with one person on screen at a time: a tall rounded window whose ring glows in the colour of whoever speaks (from segs), a dark frame round it with a haze of both colours, a shade at the window\'s foot for captions (dim), and each person\'s name chip in the window\'s top-left corner on their first turn (up to 2.6 s, gone before that turn ends); the clip\'s frame is duoWindow(\'a\', the same parameters).' },
  'common.versus': { label: 'Versus card', doc: 'A face-off card for two sides (goes with common.duo), mode picking which part of the film it serves; two-person interviews, debates, comparing two methods.' },
  'common.chart': { label: 'Data chart', doc: 'A data chart card, kind changing the chart; data is one entry per line "name|value|displayed text", hl which entry lights up (max, min or the nth), mark circle circles it, title the title, source the data source, time at is relative to the item start; look clean is simple (theme colors), hand is hand-drawn (pen picks marker / crayon / pencil / ballpoint, boil wobbles), woodcut is woodcut hatching on parchment; data, statistics, comparison, rankings, proportions, trends.' },
  'common.touch': { label: 'Touch dots', doc: 'The \"show touches\" dots of a screen recording: touches has one gesture per line, \"second|tap|x,y\" a tap, \"second-second|drag|x,y>x,y\" a drag (any number of points), \"second-second|pinch|x,y|0.4>0.15\" a two-finger pinch (the distance in short sides; growing means zooming in), \"second-second|press|x,y\" a long press; positions are fractions of the frame; a ripple rings out where the finger lands (ripple); drawn above every other item; screen recordings of using a phone, app tutorials, photo albums, chats, searches.' },
  'common.headline': { label: 'Serif card (strike, name title)', doc: 'For titles (the film\'s name, chapters, places) use common.heading (its doc-rules template is this serif card between thin rules, and the other looks, layouts, backings and entrances are there, following the film\'s title template); headline is for what heading does not do: striking words out (strikeFrom / strikeAt), the roll entrance and the look name title. The closing thank-you credits are common.outro look credits.' },
  'common.mapcam': { label: "Map camera", doc: "A camera that pans and zooms over a map photo from assets map (source = the map's source id; its longitude, latitude and zoom are kept with the download, older maps take at + zoom): cam keyframes \"seconds|place|zoom\" (empty = a slow push-in), layers stacks maps of one place at other zooms (each fades in once it covers the frame: from space down to the street), routes drawn leg by leg (an arrow, a dot or an emoji at the head), pins dropping in with names, rings, areas outlined, sea names and notes, big titles, a closing pin with a call to action; open / close grow it out of a small round map in a corner and shrink it back, mode mini is that corner map with the stop beside it; places name everything (name|Latin|lon|lat); with no map photo the world's coastline stands in. From the globe to a country use common.worldmap, then cut to mapcam (zoom ≈ log2(2π·cos lat·10^log10R / 256))." },
  'common.worldmap': { label: "Globe map", doc: "A hand-drawn world map: camera keyframes \"seconds|place|log10 radius|rotation\" fly from a globe in space (sphere, glow, graticule) down to a country, where the globe fades into a flat sea chart with rippled coasts; pins with name cards, routes as flight arcs (arc) or drawn along the places (line) with an emoji at the head (✈️ 🛵 ⛵), regions you give as a polygon or a box filled in the accent colour (on land only; there is no border data, so the shape is your points, not a real border), sea and land names, big titles; iris opens it as a circle from a point, card turns it into a small tilted map card. The coastline is Natural Earth 1:110m (enough for a country); closer than that cut to common.mapcam on a map photo. Opening locators, trips across countries, flight routes." },
  'common.notify': { label: "Notification stack", doc: "A phone's stack of notifications: items has one per line, \"seconds(-off seconds)|icon|app|title|body|key=value…\"; each comes in at its time (the newest on top, older ones pushed down; grow up is a chat, the newest at the bottom), cards past `full` pile up under the last one, \"s-s\" slides it off to the right at the second time; \"/\" breaks the body, 【word】 highlights; sub= a gloss in a second language, when= the time, tone= plain / light / dark / accent (accent: a big rounded card in the theme paper colour), lock hides the preview (a dim body and a padlock), chip= button words with chipAt= / press= unfolds a button and presses it; icons are built-in generic glyphs (bell work group cal mail phone msg mic play moon camera torch lock heart star pin bag music news plane gift sun clock user check alert app image search share trash info) or an emoji; covers a 9:16 frame, on 16:9 / 1:1 it is a phone in the middle (device); goes over common.lockscreen (y 0.43); sounds: common.buzz (vibration), common.recv (message), common.hush (muted), common.send (swiped off / sent)." },
  'common.lockscreen': { label: "Phone lock screen", doc: "A phone's lock screen over the footage (the footage is the wallpaper): status bar (time / carrier / signal / wifi / battery), a mode pill (mode, one per line \"seconds|words|plain/calm/accent|icon\"), the date, a big clock (clock \"seconds|time\", changed digits flip up), a title line (title \"seconds|words\") with count dots (count \"seconds|n\", of = how many), a live-activity bar (live \"s-s\": the clock folds away and the bar takes the top; liveLabel goes before the count), the dock (two round buttons, the unlock hint \"seconds|words|up\" — up bounces with an arrow — and the home bar; band adds a solid dark strip that hides what is under it); covers a 9:16 frame, on 16:9 / 1:1 it is a phone in the middle (device; wall gives it a wallpaper); notifications go on top with common.notify (y 0.43); sounds: common.buzz (vibration), common.recv (notification), common.hush (muted, mode change), common.tick (the clock flipping)." },
  'common.reels': { label: "Short-video frame", doc: "A short-video / story app's frame over the footage (a generic app, not any real one): mode feed runs the whole film — segment bars at the top (segs \"s-s\" separated by commas or lines; the slow one crawls and only finishes at the end; hook \"s-s|segment\" is a cold open that plays a later segment first and rewinds in its last 0.5 s with a rewind badge), the avatar with the account (handle) and a place, a title sticker (title, handwriting) with the segment chip (count), the heart / comment / share / save buttons at the right with their counts (likes, comments, shares: \"seconds|number\" one per line, eased between; counts writes them zh / ja in ten thousands (1.2 and the Chinese or Japanese sign for 10,000), en 1.2K, plain 12,345; taps are double-tap times: the heart pops and turns red; saveAt fills the bookmark), the account with a follow button (follow), the caption (caption + more), the music marquee (music) and the nav bar (nav); mode end goes over feed at the end: a pinned comment pops in (q, qName, pinLabel), the author's reply (reply, ███ becomes black bars; replyName empty = handle, authorLabel the author tag), a saved toast (toast, at saveAt), the share sheet (sheetTitle) slides up (sheetAt) and its big button (btn) is pressed at tapAt (the finger: common.touch); covers a 9:16 frame, on 16:9 / 1:1 it is a phone in the middle (device: give common.comments and common.story the same value to stack on one phone); captions with common.caption auto / big, floating hearts with common.emoji float, the double-tap heart with tap, the comment stream with common.comments, story stickers with common.story; sounds: common.rewind (the cold open rewinding), common.pop (double tap, buttons), common.recv (a comment), common.send (share)." },
  'common.comments': { label: "Comment stream", doc: "A live stream of comments over any footage: items has one per line, \"seconds|name|comment|key=value\"; each comes up from the bottom at its time (avatar, name and the words on a dark bubble, wrapped on two lines when long), pushes the older ones up, stays hold seconds and fades; the ones pushed above top fade too; color= the avatar colour (by line when absent), avatar= an emoji or letter on the avatar (the name's first letter when absent); x and w are the left edge and the widest a row gets, bottom the newest one's foot, top where they fade (-1 auto: on 9:16 the safe area's foot, clear of common.reels' buttons); uses the whole 9:16 frame, on 16:9 / 1:1 it sits on the same phone as common.reels (device; none: no phone, the whole frame); sound: common.recv (one for each)." },
  'common.story': { label: "Story sticker", doc: "A story's interactive sticker (pops in, tilted by rot, shrinks away in the last 0.2 s), kind picking a poll, an emoji slider or a timer; x, y are its centre (shares of the phone screen); uses the whole 9:16 frame, on 16:9 / 1:1 it sits on the same phone as common.reels (device); a location sticker is common.tag's label, a price common.hangtag, a text sticker common.tag / common.caption, a ring timer common.countdown; sounds: common.pop (appearing, the vote), common.tick (the timer)." },
  'common.album': { label: "Photo album", doc: "A phone's photo album as a screen recording (a generic app, not any real one: every word, tab, date, place and the status-bar time is a parameter; the icons are the built-in drawn set), five modes stacked on one phone; photos one per line \"source|seconds|corner words|x,y\" (a project source id, a video at that second; - or empty = a painted stand-in; empty corner words = a video's length, - none; x,y the thumbnail's focus), laid out as tiles by grid, while zoom, swipe and foryou take photo pick; status bar time, battery; covers a 9:16 frame, on 16:9 / 1:1 it is a phone in the middle (device; the main-track clip takes frame: screenFrame(width, height)); the finger is common.touch (albumTile(params, photo, seconds, width, height) gives where a tile is), handwritten notes common.handwrite, a white or black flash core.flash; sounds: common.tick (a tap), common.whoosh (opening, a fling, a swipe), common.thud (a pinch)." },
  'common.chat': { label: "Chat", doc: "A messaging app's conversation as a screen recording (a generic app, not any real one: every word is a parameter and the colours are its own), one item for the whole film: items one message per line \"seconds[-seconds]|who|content|key=value…\", who = me (right) / them (left, with the avatar; any other word = that group member's name) / sys (a grey system pill in the middle) / ch (a chapter pill); messages pop in at their time, the newest at the bottom, the conversation scrolling up; the kind goes after: text by default (\"/\" breaks a line, long lines wrap, the bubble's height follows its lines), typing (the other side's three dots, until their next message or \"s-s\"), photo, video (play=s-s cuts a rounded hole in the bubble while it plays: the main-track clip takes frame: chatWindow(params, message, width, height); open=s-s the bubble grows from where it sits to the whole frame and shrinks back at the second (openTime seconds each way; open=s stays open to the item's end), the block drawing that main-track clip in the growing window itself, so the clip keeps its frame, the chat behind dimming (openDim); mute icon, dur= length), album (pics=source@s,source@s,- several pictures, labels= a name on each), link (the content is the title, sub=, button=, badge= length, press= pressed), voice (dur=, play=s-s the wave fills, the content is its transcript), sticker (the content big, an emoji, no bubble); src= source id, t= the second (no source: a painted stand-in), t2= the poster after play, crop=x,y,zoom, ratio=4:5, w= width (share of the screen), tag= a label on a photo; my messages show the read mark readAfter seconds later (read changes the words; read=s per message, unread none), when= a small time; name= avatar= color= for group members; pin at the top (its title; with ch messages a row of chapter dots lights up, icon= a dot's icon, by default the emoji the chapter starts with); the header: name, status, avatar; continuing in a second item: the same params plus since=seconds (the items' clock) start this item at that second of the conversation, what came before already there, not popping in, scrolled, a played video on its t2= picture (chatWindow / chatPoint take seconds on the items' clock); the input bar types and deletes (inputs \"s-s|words|type/delete\"), hint when empty; panel the sticker panel under it (emojis, space separated; empty = none); wall \"seconds|#top|#bottom\" wallpaper colours eased between keys (noon to evening); covers a 9:16 frame, on 16:9 / 1:1 it is a phone in the middle (device); the finger is common.touch (chatPoint(params, message, seconds, width, height) gives where), a big burst sticker common.burst, floating emoji common.emoji, subtitles common.caption; sounds: common.send, common.recv, common.typing, common.buzz (left on read), common.pop (a sticker)." },
  'common.search': { label: "Search page", doc: "A search engine's pages as a screen recording (a generic dark search page, not any real engine: no logo, no coloured letters; the tabs, related searches, searching…, did you mean, the featured snippet and full-version words are all parameters), five screens by mode; times from the item's start; enter seconds pushing up from below; covers a 9:16 frame, on 16:9 / 1:1 a phone in the middle (device); the finger is common.touch (searchPoint(params, pick/bar/play, width, height) gives where), white flashes core.flash, subtitles common.caption, the ending common.outro; sounds: common.typing, common.tick (taps), common.pop (fact cards)." },
  'common.camcorder': { label: 'Camcorder viewfinder', doc: 'A home camcorder / DV viewfinder: osd sits over the footage, while ff, rew and snow fill the whole frame; every word (REC, TAPE, the months…) can be changed in words. Memories, weddings, home video, Y2K, travel DV; pair with common.film look vhs, common.beep kind rec / end and common.rewind' },
  'common.magazine': { label: 'Magazine page', doc: 'A magazine page the footage plays inside (the main-track clip with frame = magazineWindow(params) plays through its video window, a hole): magazine stock, a masthead (title) with the issue lines (issue / issueSub), the issue number and page (no / page) with a row of page squares, a double rule; tall frames put the cells under the window, square and wide frames beside it; interviews, travel issues, profiles, unboxings, rankings; turn pages with common.wipe mode curl; for just a masthead and contents over full-frame footage (a city or food magazine cover, the masthead typed in) or a one-colour back cover use common.masthead, and for a whole page with a still photo (a swatch page, a column page, under the footage) common.spread.' },
  'common.casefile': { label: 'Case file', doc: 'A fact-check case file: a kraft folder on paper with a taped-down video window (the window is a hole; the main-track clip with frame = casefileWindow(params) plays through it), a header with who said it, the claim typed in and a row of evidence boxes stamped one by one by slots "seconds|label"; at strikeAt the claim is struck out with two red marker strokes and a double-ruled "rejected" stamp lands, at closeAt a flap folds down over the window and a "case closed" stamp lands; the header sits above the window on tall and square frames and beside it on wide ones; every word is a parameter. Fact checks, call-outs, a claim against the evidence, explainers, verdicts; pair with common.thud and common.whoosh' },
  'common.beep': { label: 'Bleep', doc: 'A 1 kHz TV bleep, its length matched to the word being censored; goes with the common.censor sticker; kind rec is a camcorder\'s two short high \"beep-beep\" when recording starts, end the three beeps of a tape running out or a battery going flat (these two ignore length and frequency; DV, home videos, with common.film\'s vhs).' },
  'common.whoosh': { label: 'Whoosh', doc: 'One sweeping wind-cut sound; transitions, elements flying in and out.' },
  'common.impact': { label: 'Impact', doc: 'One low-frequency heavy hit with a long tail; a slam word landing, a title appearing, a turning point.' },
  'common.shing': { label: 'Light sweep', doc: 'The bright sound of light sweeping across (a high hiss with a falling high tone); a logo landing, light across words, a reveal.' },
  'common.air': { label: 'Breath of air', doc: 'A breath of air that swells in and fades; a picture opening, a wall appearing, a breath between parts; bright opens it up.' },
  'common.riser': { label: 'Riser', doc: 'A rising sound getting higher and louder, ending on a high point; the build-up before a turn or a reveal.' },
  'common.pop': { label: 'Pop', doc: 'A short bubble "pop"; stickers, emoji, small elements popping up.' },
  'common.thud': { label: 'Thud', doc: 'One short low thud, like a stamp coming down; goes with common.stamp; paper: a rubber stamp on a paper card on a desk (an extra wood knock and paper sound), goes with common.postmark / common.flatlay.' },
  'common.tick': { label: 'Tick', doc: 'One clean click; counting, progress, typing, text appearing character by character.' },
  'common.ding': { label: 'Ding', doc: 'One crisp ding; a right answer, a key point appearing, a flash of insight. A run of dings should climb step by step: the same pitch (the tonic), step 0, 1, 2... (scale: major / pentatonic).' },
  'common.error': { label: 'Error sound', doc: 'Two low "beep beep"s; a wrong answer, failure, NG.' },
  'common.shutter': { label: 'Shutter', doc: 'A camera shutter "click"; freeze frames, taking a photo, a Polaroid.' },
  'common.typing': { label: 'Typing', doc: 'A stretch of keyboard typing sound with adjustable length; text appearing one character at a time, searching, comments.' },
  'common.cash': { label: 'Cash register', doc: 'A cash register "ka-ching"; prices, saving money, earning money, spending big; coins adds the drawer popping open and coin sounds (totals, checkout).' },
  'common.deflate': { label: 'Deflate', doc: 'A sliding-down "pfff" deflating sound; doesn\'t count, disappointment, only a little movement, an awkward silence.' },
  'common.scratch': { label: 'Record scratch', doc: 'A record scratched to a stop, "skreee"; the mood turns suddenly, an interruption, a "wait a second" punchline.' },
  'common.powerup': { label: 'Power-up scan', doc: 'A gauge booting up: a servo motor winds up and back down, with a run of ticks; gauges, machines starting up, scanning.' },
  'common.alarm': { label: 'Alarm', doc: 'A short "beep, beep, beep" alarm (the number of beeps is adjustable); danger, about to max out, the last few seconds of a countdown.' },
  'common.explode': { label: 'Explosion + glass shatter', doc: 'A booming explosion with a low-frequency drop, then a burst of glass shards; off the charts, a mess-up, the big reveal; goes with common.burst\'s blast.' },
  'common.ffwd': { label: 'Fast-forward', doc: 'A tape fast-forward "whirr" climbing up; time fast-forwarding, skipping the wait; goes with common.timelapse.' },
  'common.page': { label: 'Page turn', doc: 'A paper page turning: a soft rustle as the sheet lifts, flips over and settles (warm, not hissy); changing steps, changing cards, opening the next page; goes with common.notecard.' },
  'common.slide': { label: 'Card slide-in', doc: 'A card sliding across a stack of paper and finally settling gently; postcards, cards, photos sliding into the frame; goes with common.flatlay.' },
  'common.flip': { label: 'Card flip', doc: 'A card on a desk flipping over: two flaps of paper and air, then settling; flipping to the back, changing sides; goes with common.flatlay.' },
  'common.xylo': { label: 'Xylophone', doc: 'One short xylophone note; list ticks, items appearing one by one (the same pitch as the tonic, step 0, 1, 2... climbing step by step, scale: major / pentatonic; or change pitch directly to make a small melody).' },
  'common.print': { label: 'Print', doc: 'The whirr of a thermal receipt printer printing (print head plus stepper motor) with adjustable length; one sound per line printed; goes with common.printer.' },
  'common.clunk': { label: 'Paper-cutter clunk', doc: 'The "clunk" of a receipt printer\'s cutter or paper-feed latch; a new section, changing shops, a machine action.' },
  'common.tear': { label: 'Paper tear', doc: 'A sheet of paper torn off with a "rrrip"; tearing a receipt, tearing a calendar, tearing it up to start over; goes with common.printer\'s tearAt.' },
  'common.rattle': { label: 'Shutter rattle', doc: 'A roll-down shutter pulled down, a "clatter" ending in one final bang; closing time, wrapping up, the end; goes with common.rolldoor.' },
  'common.dingdong': { label: 'Ding-dong', doc: 'The queue machine\'s two "ding-dong" notes (high to low, A5 to F5 by default); changing numbers, next person, changing sections, arriving at a stop; goes with common.digits\'s led.' },
  'common.ringbell': { label: 'Ring bell', doc: 'A boxing ring bell "ding, ding" (the number of rings is adjustable): a hard strike with a long metallic tail; round start, a face-off, an opening VS, the end of a match; goes with common.versus\'s round card.' },
  'common.chime': { label: 'Sparkle chime', doc: 'A glittering chime climbing up (a glockenspiel arpeggio; the number of notes, starting note and gap are adjustable; chip: 8-bit square wave); sparkly, getting prettier, a reveal, magic, a rare item; goes with the common.sparkle visuals.' },
  'common.coin': { label: 'Coin', doc: 'An 8-bit game coin "ding-ling" rising (two square-wave notes, pitch adjustable); inserting a coin, scoring, getting an item, a gacha, collecting points.' },
  'common.fanfare': { label: 'Level-clear fanfare', doc: 'An 8-bit level-clear fanfare: four notes up, then one big chord (tonic adjustable); finishing, a full collection, winning, unlocking, the ending.' },
  'common.knock': { label: 'Wood knock', doc: 'A wood "knock knock" (count, gap and pitch adjustable; lower is like knocking on a door, higher like a wooden fish); knocking on a door, a reminder, counting one by one, a zen feel.' },
  'common.boing': { label: 'Spring boing', doc: 'A cartoon spring bounce "boing"; (pitch adjustable); jumping up, popping out, bouncy, a funny rebound.' },
  'common.footstep': { label: 'Footsteps', doc: 'A run of footsteps (count and gap adjustable, the left and right foot differ in pitch; soft: soft cartoon steps, wooden floor by default); walking into the frame, walking to the next room, sneaking closer.' },
  'common.flap': { label: 'Wing flap', doc: 'Wings flapping "flap flap flap" (count and gap adjustable); a bird flying away, flying into the frame, paper flying about.' },
  'common.whirr': { label: 'Tape winding', doc: 'The "whirr" motor sound of a video tape or cassette winding (length adjustable); changing tapes, rewinding, going back in time, old video tapes; goes with common.film.' },
  'common.scribble': { label: 'Pen scribble', doc: 'The rustle of a pen writing and drawing lines on paper (length and strokes per second adjustable; crayon: thicker and grainier); handwriting, drawing circles, ticking, doodling; goes with common.handwrite / common.pen (different from the common.scratch record scratch).' },
  'common.tape': { label: 'Tape tear', doc: 'A strip torn from a tape roll with a "rrrip" and then pressed on (with press off, just the tearing); sticking on labels, notes, photos; different from common.tear (a whole sheet of paper torn off).' },
  'common.clink': { label: 'Spoon on bowl', doc: 'A crisp "clink" of a spoon touching a porcelain bowl (glass: ice against a glass, three clinks); eating, stirring, drinking soup, iced drinks, a toast.' },
  'common.drip': { label: 'Water drip', doc: 'A water drop "plink" sliding upward (count, gap and pitch adjustable); dripping water, sweating, an idea popping up, slowly accumulating.' },
  'common.sizzle': { label: 'Sizzle', doc: 'Hot oil "sizzle" as food goes into the pan, with oil pops (length adjustable); pan-frying, deep-frying, stir-frying, into the pan, piping hot.' },
  'common.pour': { label: 'Pour', doc: 'The "splash" of water or a drink being poured (length adjustable); pouring tea, pouring soup, adding sauce, filling up.' },
  'common.cry': { label: 'Baby cry', doc: 'A cartoon baby crying "waaah" (count and pitch adjustable, soft and not harsh); babies, parenting, a meltdown, crying.' },
  'common.thunder': { label: 'Thunder', doc: 'Distant thunder: a soft crack, then a low rumble rolling away for about three seconds (seed gives another roll); a storm, the sky darkening, bad news, lightning; pair with common.ambient look sky and its lightning.' },
  'common.buzz': { label: 'Phone vibration', doc: 'A phone vibrating on a table, \"bzz — bzz\" (count adjustable); a call, a notification, a message coming in, being left on read, a jolt of feeling; goes with common.touch.' },
  'common.send': { label: 'Message sent', doc: 'The short upward \"whoop\" of a chat message being sent; sending a message, posting a comment, pressing send, publishing a post.' },
  'common.recv': { label: 'Message received', doc: 'Two soft notes going up when a message arrives (the second a fifth higher, pitch adjustable); a new message, the other side replying, a notification popping up; unlike common.dingdong (a queue machine\'s two notes going down).' },
  'common.hush': { label: 'Mute', doc: 'Two notes falling, \"doo-doo\": a notification turned off, muted, an alarm silenced, a call declined, not wanting to deal with it; unlike common.deflate (a deflating slide) and common.error (a wrong answer).' },
  'common.rewind': { label: 'Rewind', doc: 'A video tape rewinding: noise sweeping from bright to dull and a whine falling down (length adjustable); rewinding, going back in time, doing it again, a recap; the opposite of common.ffwd (fast-forward climbing up).' },
  'style:pluck': { label: 'Light pluck', doc: 'Bright plucked-string arpeggios, a small xylophone melody, soft shakers and claps; cheerful daily life, food, travel, unboxing.' },
  'style:lofi': { label: 'Lo-fi', doc: 'Lazy electric-piano seventh chords, a loose swung drum kit, a soft bass; studying, chatting, daily life, nights, memories.' },
  'style:cinematic': { label: 'Cinematic', doc: 'Slowly unfolding big synth pads, long bass notes, sparse bells, a swelling drum beat; landscapes, trailers, mood, documentaries.' },
  'style:tech': { label: 'Tech pulse', doc: 'A four-on-the-floor kick, a sixteenth-note pulsing bass, offbeat open hi-hats; tech, tutorials, data, AI, editing, hardcore.' },
  'style:playful': { label: 'Playful xylophone', doc: 'A bouncy xylophone melody, a low-high oom-pah accompaniment, shakers and claps; cute, funny, kids, pets, light daily life.' },
  'style:bout-bell': { label: 'Ring rounds', doc: 'A brisk quiz-show-style pulse (minor key, 100 bpm): the opening has a boxing ring bell plus an impact; the start of every section (a new round) has a whoosh + bell "ding ding" + a low-bass impact, the end of every section has a stamp thud and a held chord, and at the very end a snare roll leads into a bright closing chord; split-screen conversations, debates, he said she said, comparing two sides (the ring-bell sound effect is also available as common.ringbell).' },
  'style:chiptune': { label: '8-bit arcade', doc: '8-bit video-game music: a square-wave lead and fast arpeggios, a triangle-wave bass jumping in octaves, noise drums, a bright major key, upbeat (150 BPM); games, gacha, card draws, collecting, clearing levels, retro.' },
  'style:funk-minor': { label: 'Minor funk', doc: '96 BPM minor funk: a plucky synth bass (octave pops), boom-bap drums, 2/4 handclaps, swung hi-hats, offbeat muted clavinet, with the drums and bass dropping out for half a beat before each section; quotes, kinetic text, punch lines, comedy, a street feel (scratch, stamp and other sound effects are placed with c.sfx).' },
  'style:garden-folk': { label: 'Afternoon kitchen', doc: 'Gentle afternoon-kitchen folk: plucked arpeggios, a music-box melody, a warm pad, light shakers and brushed drums, no kick drum; handwritten recipes, baking, handmade crafts, slow-living vlogs.' },
  'style:guzheng-pop': { label: 'Guzheng light electronic', doc: 'Pentatonic guzheng plucks (with pressed-string slides) + yueqin arpeggios + a light electronic beat (96 BPM), going from sparse to full and then returning to the guzheng; Hakka and Taiwanese tradition, modern information explainers with an Eastern flavor, cultural introductions, local food.' },
  'style:hijaz-route': { label: 'Spice route', doc: 'A Middle East / Silk Road flavor: oud plucks in the Hijaz scale over a low drone (tonic + fifth), flute, frame-drum dum/tek and shakers (84 BPM), going from sparse to full by film length, in long films leaving only the drone and bells at the seventy-percent mark, and finally returning to the theme and ending on a big chord; explainers on history, maps, seafaring, spices, ancient civilizations and markets.' },
  'style:lullaby-box': { label: 'Night-light music box', doc: 'A gentle night-light music box (72 BPM, major key): a music-box melody, a warm pad, a soft bass, felt-piano arpeggios; the middle turns to a minor key with a low heartbeat, the later part adds a glockenspiel, and before the end there is space with only a single note; parenting, bedtime, babies, warm science explainers or memories.' },
  'style:market-groove': { label: 'Night market groove', doc: 'An urban pop groove on the royal-road progression: syncopated electric-piano chords, a bouncy bass, small wood-block and xylophone hooks; lively but clean street snacks, markets, shop visits.' },
  'style:mischief': { label: 'Sneaky pluck', doc: 'A sneaky plucked groove (D minor, 120 bpm): an opening accent, one gentle bar, a layered sneaking-a-bite groove growing thicker, a held breath with only a ticking heartbeat, stacked snares, a drum roll, a bang, and an ending on a bright open D chord; funny contrast, scoring, maxing out, shorts that get more and more exaggerated.' },
  'style:postcard-felt': { label: 'Postcard felt piano', doc: 'A slow felt piano: arpeggios in the left hand, a sparse little melody in the right, an occasional music-box note; gentle, nostalgic, like a letter to yourself, suited to slow-paced travelogues and memories.' },
  'style:queue-call': { label: 'Queue-call minor', doc: 'Light xylophone + plucked bass + shakers, with the queue machine\'s "ding-dong" at the start of each section and a low drum hit before the ending; snack shops, famous queue shops, introducing shop after shop, which reason number (the number-change ding-dong sound is also available as common.dingdong).' },
  'style:quote-drop': { label: 'Quote drop', doc: 'A quiet minor-key interview bed: a heartbeat bass, muted plucks, light hi-hats; a one-bar teaser at the start (bass drone + riser + deep impact), half a bar before the quote at about sixty percent where everything stops except the riser, a deep impact and a high bell on the first beat of the quote bar, then it turns major to finish; the strongest line of a podcast quote, interview or talk (place the quote on the first beat of the bar of quoteDropPlan(bars).hit).' },
  'style:rail-beat': { label: 'Station beat', doc: '120 BPM minor electronic beat: a half-speed opening hit, a four-on-the-floor kick, a kick pulled out and a riser when changing cities and then a hit on arrival, a replay section with sixteenth-note hi-hats and a pulsing lead, a snare push, and a hit after a break to end; sections are arranged automatically by bar count; beat-synced quick cuts, travel rhythm edits, multi-city trips.' },
  'style:receipt-hop': { label: 'Receipt hop', doc: 'A light cash-counter slice of life: offbeat plucked chords, a walking bass, shakers and light claps, a little xylophone tail, small cash-register-like ticks; food spending logs, lists, shopping.' },
  'style:steelpan-bossa': { label: 'Summer steelpan', doc: 'A cool summer light bossa (100 BPM, major key): steelpan, marimba arpeggios, Rhodes seventh chords (city-pop progression), a root-fifth bass, rim clicks, shakers; mostly just a thin rhythm so people can talk, with the melody opening up only for a short middle bit and the last section; ice cream, summer, the seaside, talkative food introductions.' },
  'style:walking-pizz': { label: 'City stroll', doc: 'A strolling feel (100 BPM, light swing): plucked string chords, a wood bass walking in quarter notes, brushed drums, small glockenspiel replies, a whistled melody; map routes, shopping, strolling, eating while walking, small city trips.' },
  'style:candle-glow': { label: 'Candle glow', doc: 'A warm celebration score (72 BPM, major): electric piano motif, string pad, celesta glints, a plucked groove; it follows the film through cues: low turns minor with only a low drone, bright blooms back to major, play bounces, wait holds before a surprise, shout falls silent for the cheer, party grooves gently, quiet leaves only a pad while the room sings, tender is piano alone; birthdays, weddings, graduations, farewells, surprise parties.' },
  'style:night-studio': { label: 'Night studio', doc: 'A very quiet bed for talk (84 BPM, minor key): soft electric-piano seventh chords (i–VI–III–VII), a held pad and a sub on the root, a shaker and a bell only in the fuller bars; sits far under interviews and podcast clips without fighting the voices (gain about -19 with c.duck).' },
  'style:cold-case': {"label":"Cold case","doc":"A low suspense bed for talk clips (60 BPM, minor key): a dry wall-clock tick on every beat, a held minor drone (i–VI–iv–i), two lonely bell notes now and then; cue reveal drops everything out for 2 s, cliff cuts the music dead and leaves one low note for the end card; true crime, unsolved cases, mysteries, investigations (gain about -14 with c.duck)."},
  'style:handmade': {"label":"Handmade","doc":"A warm slow piece (72 BPM, major): felt piano, a bowed bass-like drone and a soft pad; it fills up through cues (beats adds broken chords, proof is the fullest, breath stops for a beat, we opens one slow chord, logo lands a low octave with a bell); handmade work, baking, early mornings, small-shop brand films."},
  'style:sunny-hop': {"label":"Sunny hop","doc":"A bright, bouncy score (108 BPM, major): off-beat plucks, a bass that pops up an octave, claps, a marimba hook and water-drop bloops; cues: groove brings in the drums, lift is fuller, breath drops out, rise builds up, hit lands the logo; kinetic type, outdoor, sport and playful brand films."},
  'style:circuit-pulse': {"label":"Circuit pulse","doc":"A cool, precise electronic bed (100 BPM, major): an eighth-note bass pulse, a sixteenth-note pluck arpeggio, light drums; it follows the parts through cues (build adds the arpeggio, drums the beat, full the claps, breath leaves only the pad, hit one accent on the logo); tech, app, hardware and start-up brand films and product introductions."},
  'recipe:travel': { label: 'Narrated travel', doc: 'Scene-by-scene narration with footage: captions follow the narration, one place label per scene, a title and an end card, music ducked during narration; travel, city strolls, memories.', notes: [
    'Each scene\'s length is set by its narration (narration length + gap seconds between scenes), and the shots in a scene share that time by weight; the last scene gets 1.5 extra seconds.',
    'A shot never crosses into the next scene of the footage: when the wanted length runs past the scene from sits in, from is moved earlier; if the whole scene is too short it is used as is and a warning appears in the result (use another stretch of footage or add a shot).',
    'The title is about 2.4 seconds and the end card (end) 3.5 seconds, both counted in the film length.',
    'music can be a style name, or { style, bpm, key, seed, gain }; a newly written style goes in projects/<id>/score/.',
  ] },
  'recipe:hook': { label: 'Hook short', doc: 'A hook short cut from talking footage: a panel layout, an opening burst word, a number badge and tags for each segment, speech captions (highlighting, censoring, fixing wrong words), chapter dots, and a closing call to action; food, interviews, podcasts.', notes: [
    'The layout from top to bottom does not overlap: badge and tags (0.05–0.13 of the frame height) → panel (0.15–0.62 by default) → chapter dots (right below the panel) → captions (above the bottom interface zone).',
    'panel can be given { frame: [x, y, width, height] } to move the panel; the chapter dots stay stuck below it.',
    'A censor word must be one that is really spoken in that segment (judged by the transcript); words the transcript misheard are fixed in the captions with fix (without affecting the censor matching).',
    'cta is laid over the last 2.2 seconds of the last segment.',
    'Each segment defaults to tighten: true: pauses in speech longer than 0.6 seconds are shortened to 0.3 seconds, so a segment is shorter than len; to keep the pauses (for example waiting for a punchline) give tighten: false.',
    'captions can be given the sentences to keep (for example ["fresh", "tasty"]: only captions containing those words are kept).',
    'c.recipe returns the item ids made for each segment (segments[i].clip (the first piece after trimming pauses) / pieces (all) / badge / tags / captions / progress): afterwards fine-tune any of them with c.update(id, { params: { size: 5 } }) or { transform: { x, y, scale } } (badge, tags and chapter dots hang on each segment\'s clip, and start / end given are in seconds relative to that clip).',
  ] },
  'recipe:montage': { label: 'Music montage', doc: 'Shots cut on the beats of the music: a section every four shots, a white flash and whoosh at the start of each section, a title and big text cards, a film texture; weddings, travel memories, event records.', notes: [
    'Film length = the beats of all shots × seconds per beat (60 / bpm), plus the end card (end) of 8 beats.',
    'mood decides about how long each shot stays (gentle 3.5 seconds, steady 2.5, lively 1.6, urgent 1), rounded to whole beats; rhythm defaults to varied: every four shots alternate in lengths of about "1, ½, 1½, 1" times (a section\'s total length stays the same and still lands on the bar), so they are not all the same length (like a slideshow). When beats is given it defaults to even.',
    'A shot with hero: true stays for two base lengths (the longer one when it sits at a longer position), kept for the most important picture of the film; drop is the index of that shot, and the music leaves two beats of space when it starts (a pause at the emotional peak).',
    'Give a shot\'s sound in dB (for example -14) to keep its own sound (laughter, waves); without it there is only the music.',
    'Two adjacent shots should not be adjacent positions of the same footage (it looks like a jump cut), nor have the same subject and shot size in a row; the former is warned about on save.',
    'shot in cards is a shot\'s index, counted from 0 (the first shot is 0).',
    'title can be a string, or { text, size } (size is the font size, in % of the frame height, 9 by default; reduce it for a long title); write line breaks as \\n.',
    'A shot\'s beats can be set individually (for example 8 beats for the last one), overriding mood, rhythm and hero.',
  ] },
  'clip.shake': { label: 'Camera shake', doc: 'The clip that is playing at that time shakes and then slowly settles: slam words, impacts, punchlines. To make a hook recipe\'s opening shake, add shake: true to the hook.' },
  'clip.follow': { label: 'Sticker follows the mouth (or face)', doc: 'Any sticker can be attached to the mouth or face of the person in the clip and move with them; with several people add who: left / right / largest / center. Censoring: censorSpeech(…, { follow: true }).' },
  'clip.avoidBurned': { label: 'Avoid the original\'s burned-in captions', doc: 'When the original footage\'s burned-in captions (detected during analysis) fall in this stretch, it is automatically zoomed and cropped to push the captions out of the frame, keeping the faces in the picture in frame; the zoom is capped by the resolution of the footage (beyond that it goes soft), and when the captions cannot be avoided that way, or only by cutting a face, it is left as is, our captions sitting on them that have no place of their own move to the top of the frame, and a note says so.' },
  // the clip transitions and shapes: their names are the editor's own (the Properties panel's Transition and Shape menus)
  'clip.transition.dissolve': { label: 'Dissolve', doc: 'The clip before fades out as this one fades in, the two pictures over each other: the quietest transition, a time or place changing softly.' },
  'clip.transition.slide': { label: 'Slide', doc: 'This clip slides in from one side over the one before, fading up as it comes: on to the next thing, the next place. dir sets the side it comes from.' },
  'clip.transition.wipe': { label: 'Wipe', doc: 'A straight edge sweeps across the frame with this clip behind it: a clear change of section, a before and after. dir sets where it sweeps from.' },
  'clip.transition.iris': { label: 'Iris', doc: 'This clip opens out of a circle that grows until it fills the frame: a reveal, a focus on one point; x, y are its centre.' },
  'clip.transition.clock': { label: 'Clock wipe', doc: 'A hand sweeps clockwise from 12 o\'clock, and what it has swept is this clip: time passing, a countdown, a day later.' },
  'clip.transition.bars': { label: 'Bars', doc: 'The frame in six strips turning to this clip one after another, up and down in turn: a lively change of section, the next item on a list. dir sets where it starts.' },
  'clip.transition.push': { label: 'Push', doc: 'This clip pushes the one before right out of the frame, the two moving edge to edge: on to the next stop, the timeline moving on. dir sets the way it pushes.' },
  'clip.transition.zoom': { label: 'Zoom through', doc: 'The clip before grows and blurs as the picture rushes into it, and this one settles back from a zoom: diving into the next scene, a sense of speed.' },
  'clip.transition.whip': { label: 'Whip pan', doc: 'Like a camera whipped round: both clips fly sideways together with a motion blur in the middle: fast cutting, "a second later we were in…". dir sets the way it whips.' },
  'clip.transition.blur': { label: 'Blur', doc: 'The clip before goes soft and this one fades in out of the blur, then comes into focus: a memory, a dream, a daze.' },
  'clip.transition.dip': { label: 'Dip to black', doc: 'The clip before goes down to black, and this one comes up out of it: between chapters, a long jump in time, before the end.' },
  'clip.transition.flash': { label: 'Flash to white', doc: 'A flash of white in the middle: the clip before burns to white and this one is there as it clears: a photo taken, a memory flashing up, a hit on the beat.' },
  'clip.shape.circle': { label: 'Circle', doc: 'The picture cut to a circle, centred in its window: introducing someone, a portrait, the focus on one thing.' },
  'clip.shape.ellipse': { label: 'Ellipse', doc: 'The picture cut to an ellipse filling its window: an old photograph, a soft picture-in-picture.' },
  'clip.shape.arch': { label: 'Arch', doc: 'A window round at the top and square below, never wider than tall: a view out of a window or a door, an elegant layout.' },
  'clip.shape.heart': { label: 'Heart', doc: 'The picture cut to a heart, centred in its window: something loved, a couple, a celebration.' },
  'clip.shape.star': { label: 'Star', doc: 'A five-pointed star; its points, inner corners and rounding can be set (many points and high inner corners make a burst): a highlight, a prize, a surprise.' },
  'clip.shape.ngon': { label: 'Polygon', doc: 'A regular polygon (a hexagon by default); its sides, rounding and turn can be set: triangles, diamonds, a honeycomb layout.' },
  'clip.shape.stamp': { label: 'Stamp', doc: 'A postage stamp\'s perforated edge all round: travel, a postcard, one picture of a collection.' },
  'clip.shape.bubble': { label: 'Speech bubble', doc: 'A speech bubble with a tail, tail setting where it points: who said what, a thought, a reaction shot.' },
  'clip.shape.blob': { label: 'Blob', doc: 'A soft, uneven blob that can slowly wobble (wobble): cute, handmade, a playful layout.' },
  'clip.shape.torn': { label: 'Torn paper', doc: 'Edges like torn paper, the torn sides of your choosing: a collage, a journal, a clipping.' },
  'clip.shape.brush': { label: 'Brush stroke', doc: 'One ragged brush stroke, at most 1 : 2.6 high: a painted title picture, an arty look.' },
  'clip.shape.slats': { label: 'Slats', doc: 'The picture in a few upright (or slanted) slats with gaps between them: blinds, a split showcase, a fashion look.' },
  'clip.shape.text': { label: 'Text', doc: 'The picture plays inside big letters (one line or two; few, heavy letters show the most): a title, a place name, a slogan.' },
  'caption:clean': { label: 'Clean outline', doc: 'White words with a black outline: the speech caption that stays out of the way.' },
  'caption:bare': { label: 'Plain white', doc: 'White words alone, for a picture that is dark and calm enough.' },
  'caption:darkbox': { label: 'Dark box', doc: 'White words on a see-through dark rounded box: readable over a busy picture.' },
  'caption:bubble': { label: 'Speech bubble', doc: 'Ink words in a cream bubble with a thick ink border; highlighted words in the accent colour.' },
  'caption:receipt': { label: 'Receipt slip', doc: 'Printed on a strip of receipt paper with torn edges that pops up from below.' },
  'caption:crayon': { label: 'Crayon band', doc: 'Ink words on a band of the highlight colour scribbled in crayon: picture books, handmade.' },
  'caption:snippet': { label: 'Search snippet', doc: 'A dark rounded bar with a thin colour strip at the left, like a search result.' },
  'caption:interview': { label: 'Magazine interview', doc: 'Serif words set flush left over a dark wash, with Q, A or a name in a badge at the left.' },
  'caption:autocap': { label: 'Automatic caption', doc: 'White words on a dark rounded box popping in from 0.88x, like a social app\'s automatic caption.' },
  'caption:sticker': { label: 'Big sticker words', doc: 'Big handwriting in the highlight colour with a thick black outline, popping in from 0.6x: reactions, punchlines.' },
  'caption:strips': { label: 'Notebook strips', doc: 'One slightly tilted cream strip of paper a line; the word being said gets a highlighter stroke.' },
  'caption:punch-box': { label: 'Short-video box', doc: 'White words with a heavy outline; a yellow block slides from word to word as they are said; the line pops in.' },
  'caption:punch-color': { label: 'Outline word pop', doc: 'White words with a heavy outline; the word being said takes the highlight colour and grows a little.' },
  'caption:punch-roll': { label: 'Outline roll-up', doc: 'White words with a heavy outline roll up from below and drop away at the end.' },
  'caption:double-pop': { label: 'Double outline pop', doc: 'White words with an ink and an accent outline, popping in word by word.' },
  'caption:soft-fade': { label: 'Soft shadow fade', doc: 'White words with only a soft shadow, fading slowly in and out: for a calm picture.' },
  'caption:frost-color': { label: 'Frosted glass words', doc: 'A frosted-glass box; the word being said turns pale blue and grows; blurs in.' },
  'caption:frost-underline': { label: 'Frosted glass underline', doc: 'A frosted-glass box; a line draws under each word as it is said.' },
  'caption:cinema': { label: 'Film subtitle', doc: 'Medium-weight, slightly spaced white words with a tight shadow, fading in and out like a film subtitle.' },
  'caption:cinema-type': { label: 'Typewriter subtitle', doc: 'The film subtitle typed out letter by letter as it is said, a caret following.' },
  'caption:slab-wipe': { label: 'Slanted blocks wipe', doc: 'White words on a slanted block of the accent colour a line, wiped in and out from the left.' },
  'caption:hollow-color': { label: 'Hollow word pop', doc: 'Outlined letters only; the word being said fills with the highlight colour; zooms in from big.' },
  'caption:marker-fill': { label: 'Highlighter light-up', doc: 'Ink words on a highlighter stroke a line; words not said yet are faint.' },
  'caption:neon-fill': { label: 'Neon light-up', doc: 'Pink neon-tube words, dark until said, then lit; the word being said glows blue.' },
  'caption:neon-wave': { label: 'Neon wave', doc: 'Blue neon words bobbing gently, glitching in.' },
  'caption:gradient-zoom': { label: 'Gradient big words', doc: 'Big words in a white-to-orange gradient with a hard dark edge; the word being said in a blue gradient; zooms in.' },
  'caption:gradient-one': { label: 'Gradient one word', doc: 'One big gradient word at a time in the middle of the picture.' },
  'caption:extrude-one': { label: 'One word at a time', doc: 'Yellow 3D letters, one word at a time in the middle of the picture, popping in.' },
  'caption:extrude-stretch': { label: '3D bounce', doc: 'Yellow 3D letters stretching in, the words popping one by one.' },
  'caption:sticker-pop': { label: 'Handwritten sticker', doc: 'Handwritten sticker words with a white edge, dropping in and popping word by word; highlights in red.' },
  'caption:sticker-wave': { label: 'Sticker wave', doc: 'Handwritten sticker words gathering from all sides, then bobbing gently.' },
  'caption:heavy-rise': { label: 'Heavy shadow', doc: 'Black-weight words with a hard shadow dropped down and right, like a poster.' },
  'caption:heavy-pop': { label: 'Heavy shadow pop', doc: 'Black-weight words with a hard shadow, popping in word by word.' },
  'caption:offset-color': { label: 'Misprint', doc: 'Highlight-coloured words with a second-colour copy out of register, like a misprint; the word being said turns white.' },
  'caption:offset-glitch': { label: 'Misprint glitch', doc: 'Misprinted words glitching in and wiped away.' },
  'caption:gold-zoom': { label: 'Polished gold', doc: 'Polished gold gradient letters with a brown edge, zooming in; the word being said turns bright gold.' },
  'caption:gold-one': { label: 'Gold one word', doc: 'One big gold word at a time in the middle of the picture.' },
  'caption:chrome-flip': { label: 'Chrome flip', doc: 'Cold silver chrome letters flipping in.' },
  'caption:chrome-color': { label: 'Chrome words', doc: 'Chrome letters; the word being said takes a blue metal sheen.' },
  'caption:flow-fade': { label: 'Flowing gradient', doc: 'A blue and pink gradient flowing through the words.' },
  'caption:flow-wave': { label: 'Flowing wave', doc: 'Yellow-orange flowing gradient words bobbing gently.' },
  'caption:halo-fill': { label: 'Soft glow light-up', doc: 'White words in a soft pink glow; words not said yet are faint.' },
  'caption:halo-blur': { label: 'Soft glow blur', doc: 'White words in a soft blue glow, blurring in and out.' },
  'caption:duotone-pop': { label: 'Two-tone pop', doc: 'Words yellow above and pink below, popping in word by word.' },
  'caption:duotone-slide': { label: 'Two-tone slide', doc: 'Words teal above and blue below, sliding in and out.' },
  'caption:longshadow-drop': { label: 'Long shadow drop', doc: 'Words casting a long shadow down and right, dropping in word by word.' },
  'caption:longshadow-one': { label: 'Long shadow one word', doc: 'One big long-shadowed word at a time in the middle.' },
  'caption:emboss-fade': { label: 'Embossed plate', doc: 'Letters pressed into a grey plate, fading in and out.' },
  'caption:emboss-type': { label: 'Embossed typing', doc: 'Embossed letters typed out as they are said.' },
  'caption:block-bounce': { label: 'Toy blocks bounce', doc: 'White toy-block letters with a thick ink outline and a deep side in the main colour, words popping one by one.' },
  'caption:block-color': { label: 'Toy blocks words', doc: 'Toy-block letters; the word being said takes the highlight colour.' },
  'caption:puffy-pop': { label: 'Puffy pop', doc: 'Round inflated pink letters with a thick white rim, popping in word by word.' },
  'caption:puffy-wave': { label: 'Puffy wave', doc: 'Pale blue puffy letters stretching in, then bobbing gently.' },
  'caption:tape-wipe': { label: 'Washi tape', doc: 'A strip of mint washi tape a line with ink words, wiped on and off from the left.' },
  'caption:tape-color': { label: 'Washi tape words', doc: 'Apricot washi tape; the word being said takes the main colour.' },
  'caption:postit-type': { label: 'Sticky note', doc: 'A slightly turned yellow sticky note, the handwriting appearing as it is said.' },
  'caption:postit-flip': { label: 'Pink sticky note', doc: 'A pink sticky note flipping in.' },
  'caption:label-type': { label: 'Label maker', doc: 'A black label-maker strip a line with white embossed capitals, typed as it is said.' },
  'caption:label-stretch': { label: 'Label maker stretch', doc: 'Label-maker strips stretching in and shrinking away.' },
  'caption:ransom-pop': { label: 'Cut-out letters', doc: 'Every character on its own scrap of paper in a different colour, font and tilt, popping in word by word.' },
  'caption:ransom-scatter': { label: 'Cut-out gather', doc: 'Cut-out letters gathering from all sides, falling away at the end.' },
  'caption:rgb-glitch': { label: 'RGB glitch', doc: 'White words with red and cyan copies pulled apart, glitching in and blurring away.' },
  'caption:rgb-color': { label: 'RGB words', doc: 'RGB-split words; the word being said takes the highlight colour.' },
  'caption:pixel-type': { label: 'Pixel typing', doc: '8-bit game letters typed out as they are said.' },
  'caption:pixel-pop': { label: 'Pixel pop', doc: '8-bit letters popping in word by word, highlights in green.' },
  'caption:vhs-type': { label: 'Tape typing', doc: 'A camcorder\'s monospaced capitals typed out as they are said.' },
  'caption:vhs-fade': { label: 'Camcorder text', doc: 'A camcorder\'s on-screen white text with a colour fringe, glitching in.' },
  'caption:terminal-type': { label: 'Terminal', doc: 'Green monospaced text in a dark console box, typed as it is said with a caret.' },
  'caption:terminal-color': { label: 'Terminal words', doc: 'Terminal green text; the word being said turns bright white.' },
  'caption:segment-type': { label: 'LCD display', doc: 'Dark characters on a grey-green LCD panel, appearing as they are said.' },
  'caption:segment-roll': { label: 'LCD roll-up', doc: 'The LCD panel rolling up into place.' },
  'caption:scanline-glitch': { label: 'Scan lines', doc: 'Blue letters striped by scan lines, glitching in like an old screen.' },
  'caption:scanline-fill': { label: 'Scan lines light-up', doc: 'Orange scan-line letters; words not said yet are faint.' },
  'caption:news-wipe': { label: 'News bar', doc: 'Ink words on a white bar with a block of the main colour at its left, wiped in and out.' },
  'caption:news-slide': { label: 'News bar slide', doc: 'The news bar sliding in from the left; the word being said takes the main colour.' },
  'caption:chat-pop': { label: 'Chat bubbles', doc: 'Speakers 2 and 3 in main-colour bubbles on the right, everyone else in grey on the left, popping in.' },
  'caption:chat-type': { label: 'Chat typing', doc: 'Chat bubbles with the words typed as they are said.' },
  'caption:lyric-fill': { label: 'Lyrics', doc: 'A classical serif in soft-glowing white; the word being sung lights in gold, the rest dim until sung.' },
  'caption:lyric-blur': { label: 'Lyrics blur', doc: 'Lyric lines blurring in and out.' },
  'caption:dialog-type': { label: 'Game dialogue', doc: 'A dark blue game dialogue box with a double frame, the words typed as they are said.' },
  'caption:dialog-roll': { label: 'Game dialogue roll-up', doc: 'The game dialogue box rolling up and shrinking away.' },
  'caption:comic-bounce': { label: 'Comic panel', doc: 'A white panel with a heavy ink border over halftone dots, stretching in.' },
  'caption:comic-pop': { label: 'Comic panel pop', doc: 'A comic panel with blue halftone, the words popping one by one.' },
  'caption:chalk-type': { label: 'Chalkboard', doc: 'Chalk words on a blackboard, written out as they are said.' },
  'caption:chalk-fade': { label: 'Chalkboard fade', doc: 'Chalk words on a blackboard fading in and out.' },
  'caption:comic-narration': { label: 'Comic narration', doc: 'A comic narration box: ink words on yellow with a thin ink border, wiping in at the top left (goes with the comic page).' },
  'caption:desk-type': {"label":"Desktop message","doc":"A message box like a pastel retro window (a pink title band, an ink border, a hard shadow), the words typed as they are said (goes with the retro desktop)."},
  'caption:scrap-chip': {"label":"Scrapbook chip","doc":"White serif words on a small torn chip of coloured paper, tipped a little (goes with the scrapbook prints)."},
  'caption:mono-box': {"label":"Mono box","doc":"Bold white words in a small black box with a thin white line just inside its edge (goes with the word frame; for white with black, set color black and outline white)."},
  'caption:editorial-bar': {"label":"Editorial bar","doc":"Black serif words on white with a thin bar in the theme's second colour (accent2) at the left, set flush left: a magazine-style caption (goes with the masthead and spreads)."},
  'caption:color-boxes': {"label":"Stacked boxes","doc":"Each line on its own square block of the accent colour, heavy black words, flush left, wiped in: fast beat cuts (goes with common.grade and common.poster)."},
  'caption:story-serif': {"label":"Mustard serif","doc":"Mustard serif words, centred, fading in and out, on the plain colour blocks above and below a shot (common.backdrop solid and a clip frame): storybook and Wes Anderson-style travel films (goes with the storybook title template)."},
  'caption:pop-box': {"label":"Black box serif","doc":"Heavy white serif words in a black box, popping in; Dopamine-colour hauls, lists and outfits (with the title template pop and common.popcard)."},
  'common.dachshund': { label: 'Dachshund', doc: 'Tellcut\'s own dachshund: black and cream, its body a strip of film. It walks, wags its tail, tilts its head, sits, and cuts itself in two like a clip; the film frames can show your footage. Only when the user asks for the Tellcut dachshund.' },
  'common.audiogram': {"label":"Audiogram","doc":"A waveform that moves with the speech, to carry a podcast or interview that is only sound. The sound comes from the footage's analysis: one item for the whole exchange follows the speech playing on the audio tracks (a tightened talk too; source picks one footage when other audio clips play), or hang it on one clip with c.attach(c.effect('common.audiogram', { at, len, look }), clipId) and trims and moves stay in step; at ties the item's start to that second of source. speakers [[from, to, who]] (footage seconds, written as for c.speechCaptions) with names ['', 'A', 'B']: the colour and the name tag change the moment the speaker does (theme accent, accent2 by default; colors overrides); hold (seconds) keeps the last speaker's colour and name tag through a gap shorter than that between two pieces of sound or two speakers; only (which speaker) makes it move only while that speaker talks, always in their colour with their name (one audiogram per person). A cover from art (a file in the project) or artSource + artT (a frame of footage); a cover that is not square is scaled to cover and its overflow cut off evenly from the centre, so keep what matters in the middle; arts [[from, to, file], …] (footage seconds, like speakers) changes the cover over time, art at other times. x y w h place it; nameX nameY the name tag's centre; fadeIn fadeOut fade it in and out; gain and smooth tune the level. With no audio at all it draws made-up levels. Background, show title and captions are common.backdrop, common.header and common.caption."},
  'common.quiz': {"label":"Quiz card","doc":"A game-show quiz question on a paper card with a bold ink border: a tab on its top edge with the question number (no) and difficulty stars (stars 1–5); the question types in between the qt \"start,end\" seconds; the options (options split by |, 2–6, letters before them) pop in at the shows seconds, the card growing with them; at reveal the wrong ones get a red cross and grey out, the answer (answer, counted from 0) turns green and glows, then the wrong rows fold away, the answer slides up to the first row and a badge pops onto its right end (badge an emoji or a word, badgeSource a frame of a source as the picture: a flag, a product photo); fact is a number chip that drops in above the card after the reveal (factSub its source); y -1 puts the full card (all options shown) on the bottom safe line; quizzes, guess-the-answer, trivia, multiple choice; sounds: common.pop (options), common.buzz (cross), common.ding (right), a countdown with common.countdown."},
  'common.doodle': {"label":"Hand doodle","doc":"A hand doodle drawn stroke by stroke in marker: data is the stroke list as JSON [{a,b,p:[x,y,…],c,w,d,g,k,o}] — drawn from a to b seconds, p points as fractions of the frame, c colour, w width, d dashed, g a group that sways together (jig how far), k [period, phase, share on] blinks once drawn, o opacity; boil re-wobbles the lines that many times a second (wob how far); from erase seconds a board eraser sweeps the box ex0–ex1, ey0–ey1 from top to bottom, wiping it off; whiteboard explainers, notes, diagrams, drawing it out; for one ready-made circle, arrow or tick use common.pen, to trace a shape across a cut common.pen trace; sounds: common.scribble (lines, the eraser)."},
  'common.healthbar': {"label":"Live header + health bar","doc":"A live-replay header card: a top row with a red LIVE pill (blinking dot), a grey replay pill and a one-line title (each may be blank; all blank drops the row), under it a name and a segmented game health bar; stops \"seconds:HP 0–100\" comma-separated: a hit shakes the card and leaves a white trail that catches up, a heal flashes the cells white, the state word on the right follows the HP (states \"high,mid,low,broken\"); the stop written x shatters the bar: the cells fly apart, the frame turns red and dashed and the last state word is stamped on; live highlights, reactions, challenges, showdowns, will-they-hold-out; y -1 sits on the top safe line; sounds: common.hit or common.thud (a hit), common.glass (shattering)."},
  'common.tabletop': {"label":"Tabletop","doc":"A table surface for the whole film, under the video (static): look steel is brushed stainless steel (hairline grain, a warm pool of light from a lamp above, a slanted sheen), wood a wooden table (planks, grain, a warm lamp at the upper left); color changes the surface colour, light the lamp colour; grill sets a charcoal grill into a corner (an iron ring, glowing coals, the grate: barbecue, hot pot, street food); food, unboxing and handmade films, the ground under a video panel, a receipt printer or cards on the table; a paper desk is common.paper."},
  'common.leak': {"label":"Light leak","doc":"A light leak: light drifting slowly across the frame from a corner or side and fading away (screen blend, it only brightens; no grain, no flicker); travel 0 keeps it at (x, y), fading in and out and breathing a little (a low sun in a corner); color, core and rose change the colours, blue and white make it a cold light. look changes the kind of light (the same path and brightness)."},
  'common.comic': {"label":"Comic page","doc":"A comic page the footage plays in: white gutters, slanted panels with ink borders, the panels sliding in one by one, manga focus lines inside a panel; layout picks the page, panels draws your own (one a line, \"x,y x,y x,y x,y\" in frame fractions); times and from give each panel's second and side (comma lists; missing ones come 0.6 s apart, right and left in turn); focus has one line of focus lines a line, \"panel|x,y|seconds\"; a clip goes in panel n with frame: comicWindow(n, the same params) (from @tellcut/plugin-common): the main-track clip in one panel, c.beside clips in the others; one item a page, another for the next page; goes with common.onomatopoeia sound words, the comic-narration caption template, burst's dots and shadow, glitch for turning the page."},
  'common.onomatopoeia': {"label":"Sound word","doc":"A comic's sound word (HAHA!, SNIFF, Zzz…): big letters appearing one after another, anywhere in the frame at a slant; look picks how that kind of sound is drawn; rise makes each letter higher than the last (a laugh climbing), vertical stacks the letters top to bottom (rise then shifts them sideways); color is the main colour, color2 the second, ink the ink; for English pick a font such as Bangers and a little more spacing; a big word and a small English one can share a frame; goes with common.comic, common.speedlines and the pop sound."},
  'common.desktop': {"label":"Retro desktop","doc":"A pastel retro computer desktop for the whole film: a gradient that changes colour each chapter (a faint grid, pixel clouds drifting, twinkles), a menu bar (menu) and the program name top right (app), a globe and three folders, and a taskbar with a ★ Start button and one .exe button a chapter, the current one lit (the film's progress is on the taskbar); chapters has one chapter a line, \"seconds|name|top colour|bottom colour\"; goes with common.window (each flies into its chapter's button at the end), common.popup, common.touch's cursor look and the desk-type caption template; birthdays, parties, memory albums, \"open the files\" round-ups."},
  'common.window': {"label":"Retro window","doc":"A retro computer window: a title bar (title, three buttons; bar lav, pink, mint, yellow or a colour), an ink border and a hard shadow, content picking what is inside; it pops in, and at its end (exit) min flies into taskbar button slot (of slots, as common.desktop's chapters), close shuts it, max grows it over the top of the frame at maxAt (maxH tall, the title bar fading), none leaves it; a chapter stacks a few windows at a slant; goes with common.desktop and common.popup."},
  'common.popup': {"label":"Retro dialog","doc":"A retro computer dialog: mode dialog is a small \"notice\" window with a question (text) and two buttons (buttons \"main|other\", the first yellow), button pick pressed at press, popping in and closing at the end (\"Cancel the party?\" [Cancel] [Wait]); mode sheet is a closing panel: a cream sheet rising from the bottom, text typed on it, and a button (the first of buttons) pressed at press that turns into done (\"Save memory → Saved ✓\") and throws pixel confetti; goes with common.desktop, common.window and common.touch's cursor look (point it at the button)."},
  'common.prints': {"label":"Scrapbook prints","doc":"A scrapbook page of prints: prints has one a line, \"seconds|source seconds|x,y,width|tilt|width:height|options\" (x, y fractions of the frame, the width a fraction of its short side); each is a still of the footage (source; src=source gives one print a source of its own) with a deckled white border and a soft shadow, dropping from a little big and turned into place; options tape (washi tape, tape=#colour), clip (a paperclip), crop=x,y,zoom (frames it like a clip's crop and the other photo cards: x, y the point to aim at, zoom 1 and up enlarges; e.g. away from the source's own text; the older focus=x,y still reads); one item a page, over full-frame footage or a paper page (common.paper), a later big print covering the ones before; goes with common.scraps, the scrap-chip caption template, the scrapbook-card title template and common.wipe's tiles; travel, family and pet scrapbooks, memory albums."},
  'common.scraps': {"label":"Paper scraps and tape","doc":"What gets pasted round the prints, scraps one a line \"seconds|kind|x,y,w,h|tilt|colour\" (x, y fractions of the frame, w, h fractions of its short side), each popping on at its second: paper a torn scrap, dots halftone washi tape, tape translucent tape, pin a round pin (w its diameter), clip a paperclip, grid thin white seams over the whole frame (the position is \"columns,rows\"; keeps the seams after common.wipe's tiles); goes with common.prints, scrap-chip and scrapbook-card."},
  'common.monoframe': {"label":"Word frame","doc":"A black-and-white frame of words round the picture: diagonal bands, ink with paper words and paper with ink words by turns, text repeating and drifting along them (speed), a rounded window in the middle showing the footage (border is the frame's width, a fraction of the short side); win moves the window (\"seconds|x,y,w,h\" a line in frame fractions, e.g. shrink it to a strip in the middle, then open it up again), full fills the frame with words; one item a chapter, new words each chapter (a city, a theme, any language); goes with the mono-cycle title template, the mono-box caption template, common.wipe's vortex for chapter turns and common.filmstrip; travel, city and food shorts with a street-fashion feel."},
  'common.filmstrip': {"label":"Film strips","doc":"A page of two 35 mm film strips, one scrolling up and one down (speed is frame heights a second), their frames holding stills of the footage (source) at the seconds in stills (comma-separated, taken in turn), sprocket holes down both sides and edge numbers between frames (label plus 21A, 22A…); bg is the base colour; put it under the footage as a whole page (layer: under) with captions over it; a look back, \"so much more to remember\", a trip's round-up; pick shots without the source's own text (frames are not cropped)."},
  'common.masthead': {"label":"Magazine masthead","doc":"A magazine's cover and back cover: mode front lies over full-frame footage, its masthead (title) typed a letter at a time with a rule drawn out under it, two small issue lines in the top corners (issueL, issueR), the contents down the right a line at a time (contents, one a line), an italic line wiped in at the lower left (script); mode back is the back cover: a page in color with NEXT ISSUE / SEE YOU AGAIN, the masthead, a rule, the issue (sub), a band of photo in the middle (source at t) and an italic line under it (script); a magazine-style opening and ending for travel, city and food films, with common.spread pages, common.wordbands, the didone-full title template and the editorial-bar caption template between; for footage playing in a window of a magazine layout (inside pages, lists, a cover with cover lines, a back cover with a button) use common.magazine, while the masthead lies over full-frame footage or makes a one-colour back cover; it also takes common.magazine's parameter names: layout (cover = front, back), issue (top right), no (top left), accent (the back cover's colour)."},
  'common.spread': {"label":"Magazine spread","doc":"A whole magazine page (put it under the footage, layer: under, with captions over it), its photo a still of source at t (fx, fy frame it): layout swatch is a colour page of a \"taste index\": the page in color, the column's name (header) and n / total at the top, a big photo, a big serif number (no) and a name (name), a swatch card at the lower right in the page's colour with a code (code) and a colour name (cname), which can be made-up type; layout column is a column page on paper: a big number at the top left, a photo card laid over it, a big outlined word over the photo's foot (word), the column's name at the top right and a page number (page); one item a page, cutting straight to the next (with the page sound); food lists (a colour a dish), a city's places, a catalogue; goes with common.masthead and the editorial-bar caption template; its photo is a still and the page lies under the footage: for footage playing in a window of the layout use common.magazine; it also takes common.magazine's name kicker (= header)."},
  'common.wordbands': {"label":"Word bands","doc":"A run of slanted bands, repeated italic serif words sliding along them, a white-bordered photo in the middle (source at t): bands has one band a line, \"seconds|word|band colour|word colour\", each coming in at its second about twice as wide as the one before, the last filling the frame; bg is the base colour; put it under the footage as a whole page (layer: under); one-word-a-beat slogans like EAT · EVERY · SINGLE · BITE, a beat between chapters, food-magazine films; goes with common.masthead and common.spread."},
  'common.grade': {"label":"One-colour grade","doc":"Switches the footage under it on the beat: one item over the whole film, steps \"seconds|bw/mono/none\" (the item's own seconds, one a line) turn the picture black-and-white, a single colour (color), or leave it as it is (#colour = one-colour in that colour); deep makes the one colour richer: a light tone multiplied over the mono steps, so bright skies take the colour too (what a separate common.wash did); captions and text blocks go after it so they keep their colours; fast cuts of sport, cycling and travel, with common.viewfinder, common.echo and common.poster."},
  'common.wash': {"label":"Colour wash","doc":"An old block (new films use common.grade's deep): multiplies a light colour over the mono steps so the bright parts take the colour too; put it after common.grade with the same steps (bw and none steps are left alone)."},
  'common.viewfinder': {"label":"Viewfinder","doc":"A viewfinder over the whole film: corner brackets in color (growing in at the start), a title at the top left with a chapter line under it (chapters, \"seconds|words\", changing on time), a route at the top right with a shot counter (cuts, the seconds of each cut, comma-separated, shown as 05 / 16), a tick ruler down the left with a needle walking down it over the film; the small lines are ornaments, not captions; with common.grade and common.echo."},
  'common.echo': {"label":"Echo word","doc":"A big heavy slanted word (Anton) with a few outlined copies of it round it (look picks how they lie, echoes how many), the word popping a little larger and settling; label is a small number over its left end (01, 02 for places or chapters); a word too wide shrinks to 74% of the frame width; on the one-colour (common.grade mono) stretches the word and copies turn onMono, where an orange word on an orange picture would vanish: with steps empty it follows the film's common.grade at that moment, steps of its own (in this item's seconds; 0|none = never) decide instead; place names and action words in sport and travel cuts (RIDE, WALK, PARIS)."},
  'common.poster': {"label":"One-colour poster page","doc":"A whole page in one colour (color) for a stretch with no footage: a faint giant outlined word drifting behind (ghost, empty = the top word), a heavy slanted word on top (top) dropping in and one below (bottom) rising, a photo card in the middle (corner brackets in mark, a hard black shadow, settling as it comes in; photos one a line \"source|seconds|fx,fy\", several taking turns every every seconds for dishes or sights), a line of upright text down its right (side), and with barcode a barcode and a line of small text at the lower left (an end card); chapter pages, list pages, a closing KEEP / GOING.; captions go under the bottom word."},
  'common.band': {"label":"Tape band","doc":"A band slanting across the whole frame, a heavy slanted line of words (words, end it with \" / \" as a divider) repeating along it and scrolling, wiped in at the start; look picks what the band looks like; angle and y place it; an ornament, not a caption; beat words like KM BY KM or CITY BY CITY, with common.whoosh."},
  'common.binocular': {"label":"Binoculars","doc":"Looking through binoculars: the picture covered in color (black by default) but for two overlapping round windows side by side (shape binocular; spyglass is one round window), soft at the edge, opening from small over open seconds at the start; cx and cy place the centre (fractions of the frame), r is the radius (a fraction of the frame's short side), overlap how much the two circles overlap (a fraction of the radius); aim the windows at the subject by moving cy / cx, which is easier than changing the clip's crop; captions go on the black under the windows; peeking, spotting something far off (a cat on a wall, a bird, someone across the street), storybook and Wes Anderson-style travel films."},
  'common.photostack': {"label":"Photo stack","doc":"A few rounded photo cards stacked down a plain page (bg): cards one a line, \"source|seconds|label|x,y,zoom\" (a clip gives its frame at that second; x,y,zoom framed like a clip's crop, x, y the point to aim at, zoom may be left out), one sliding up every every seconds, a thin edge (edge), a soft shadow and an italic label at the lower right (in label, lovely in lower-case English); w is the card width (a fraction of the frame's short side), aspect its height to width, top the first card's top edge; when they do not fit, the whole stack shrinks so the last stops above the captions (the safe area's bottom); put it on a stretch with no footage (layer under); the few things of a day eaten, drunk or seen laid out at once, storybook and Wes Anderson-style travel films, with common.shutter."},
  'common.popcard': {"label":"Pop card","doc":"A slightly tilted white photo card (a thin ink line, an offset block of shadow colour at its lower right) pops in and plays its own shots: shots one a line, \"seconds|source|source seconds|x,y,zoom|label|still\" (seconds from the item's start, each running until the next line; x,y,zoom the crop; still holds a frame), the card giving a little bump at each cut; the label is a pill in the pill colour on its top left corner (pillSide right: top right), popping only when it changes; x, y, w, h the card's box (frame shares), tilt its angle. When the whole page is cards the main track holds no clip, with common.backdrop (pattern words) under them. Hauls, unboxings, outfits, one item after another (Dopamine colours, with common.sticker, common.badge's box and the title template pop); a few small cards side by side make the closing round-up."},
  'common.sticker': {"label":"Flat sticker","doc":"A small flat sticker with a thick ink line and a solid shadow offset to the lower right, popping in tipped and small, then wobbling a little; x, y its centre, size its width (a share of the frame's short side). On a card's corner or beside a title (Dopamine-colour hauls, lists, vlogs, with common.popcard; a burst with words is common.burst with a shadow, a pointer common.touch's cursor)."},
  'common.grid': {"label":"Clean grid","doc":"A clean grid layout: a few square-cornered (or rounded) cells with thin gaps on a plain ground (gutter), each playing its own shot and coming in one by one (reveal: fade, scale, slide or wipe; the picture moves with its cell). layout picks the arrangement (a wide film turns them side by side); boxes draws your own cells (one a line, \"x,y,w,h\" frame shares). shots is one line a cell, \"source|source seconds|x,y,zoom|still\" (the cell plays from source seconds when it comes in; still holds a frame; a cell with no line shows a stand-in picture); times and from are when and from where each cell comes in (comma lists; missing ones 0.4 s apart, left and right in turn); after exitAt the cells go back the way they came. The cells' videos are silent (sound comes from the score, the voice-over or a clip on a track); when the page covers everything the main track can stay empty. Unlike the comic page: no ink lines, no focus lines. Round-ups, before and after, lists, several places at once."},
  'common.slant': {"label":"Slanted bands","doc":"The frame cut into 2 or 3 full-bleed bands (count; parallel slanted edges at angle degrees), each playing its own shot and rushing in from the side with its picture, in turn; stacked on a tall film, side by side on a wide one; a thin seam between bands (seam, 0 = none), bg showing where no band has come in yet. shots is one line a band, \"source|source seconds|x,y,zoom|still\" (the band plays from source seconds when it comes in; a band with no line shows a stand-in picture); times and from are when and from where each band comes in (comma lists; missing ones 0.35 s apart, left and right in turn on a tall film, top and bottom on a wide one); labels puts a small tag in each band's corner (comma-separated, for example BEFORE,AFTER); after exitAt the bands slide back out. The bands' videos are silent (sound comes from the score, the voice-over or a clip on a track); when the page covers everything the main track can stay empty. Before and after, sport, an opening of three quick shots."},
  'common.postage': {"label":"Postage stamp","doc":"A postage stamp with perforated edges drops in (or slides in from a side) and plays a shot in its picture (source, from = source seconds, crop, still = a held frame; a stand-in picture when there is no source); the picture moves with the stamp and keeps the stamp's slight tilt once it has settled. The stamp's value and a small line are printed in the margin below the picture, and at markAt a round postmark (place, date) thumps down across its bottom-right corner. backdrop is what lies underneath (desk = a wooden desk, color = plain, none = see-through). The stamp's video is silent. Unlike common.flatlay (the 3D desk: postcards, photo frames; the stamp on a postcard's back is a still stuck to the card), common.postmark (only the postmark) and common.stamp (a rubber stamp): one flat stamp, the video playing in its picture, and it can lie see-through over the video. Several things together on a 3D desk are flatlay; one stamp carrying a frame is this. A stop on a trip, a moment from a memory."},
  'common.letterbox': {"label":"Widescreen bars","doc":"Cinema bars slide in from the top and bottom edges, leaving a picture of width-to-height ratio in the middle (0 = automatic: 2.39 on a wide frame, square on a tall one), with a spaced-out title and a small sub line set in the bars: on a tall film both in the top bar, below the platform's top band (no words when the bar is not deep enough); on a wide film the title in the middle of the bottom bar and the small line in the top bar. titleAt is when the words fade in (-1 = when the bars are in place); after outAt the bars go back. Unlike common.film's letterbox parameter, these bars move and carry words. A cinematic opening, chapter titles."},
  'common.bounce': {"label":"Bouncing words","doc":"Big kinetic type: items has one phrase a line, \"seconds|text|size|colour|x|y|mode|options\", the characters entering one by one on the beat; mode drop falls in, squashes and bounces, pop springs out of nothing, slam lands from big, float rises and drifts up, sway pops in and rocks, knock is cut-out type: a coloured sheet (sheet, down to sheetTo) covers the frame and the letters are holes showing the video underneath; options jump=s/s hops, sink=s drops the 【stressed】 characters off the bottom, out=s shrinks it away, wob=1 wobbles once landed, stagger=s the gap between characters, shadow=1 a drop shadow, scrim=1 a dark band behind the words, emph=colour the stressed colour; size is px at a 1080 short side (too wide shrinks into the safe area), colour empty = color, hl = the accent; manifestos, brand films, slogans, on-the-beat type, opening hooks."},
  'common.token': {"label":"Coin sticker","doc":"A hand-drawn gold coin sticker (white sticker edge, floating gently) with a marker label on white tape beside it; steps has one step a line, \"seconds|label|word on the coin|none/miss/made\": when the label or the coin's word changes the coin flips over to the new face, miss draws a red cross stroke by stroke and made a green tick (the label turns green too); enter pops it in, exit shrinks it away at the end; which attempt, a wish, a challenge passed or failed, collecting points, levels; goes with common.coin (coin in), common.error (fail), common.ding (success)."},
  'common.heading': {"label":"Title","doc":"A title (a film's name, a chapter, a place, an ending): its look (style: the caption looks plus a title's own), layout, backing, entrance, exit, colours and font combine freely; the usual combinations are named title templates (npm run tellcut -- catalog TTL lists them; put the id in template, c.titleTemplate for a whole film). kicker is a small line above the title, sub a smaller line under it; a 【word】 turns the highlight colour. layout: center, top, bottom, lower (bottom left, a big lower third), left (left, middle height), corner (small, top right), full (grown to fill the safe width). backing: band (a dark band across the frame), scrim (the whole frame darkened), blur (the whole frame blurred), card (a solid card), rules (a thin line above and below), bar (a colour bar at its left), black (all black). Entrances of its own: track (letters closing up), mask (rising out of a mask), open (opening from the middle), focus (from a blur into focus), rule (the lines first, then the words); exits: spread (letters spreading apart), sink (sinking into a mask)."},
  'title:plain-center': {"label":"Centred white","doc":"White words in the middle, fading in and out: the quietest title, for a clean frame"},
  'title:doc-rules': {"label":"Documentary rules","doc":"A serif title; thin lines above and below draw out from the middle before the words: documentary and essay films, their names and chapters"},
  'title:lower-bar': {"label":"Lower left bar","doc":"Heavy type at the bottom left with an accent bar at its left, wiped in: places, names, section titles"},
  'title:neon-scrim': {"label":"Neon over dark","doc":"The whole frame darkened, a neon line focusing in from a blur: night scenes, parties, openings"},
  'title:gold-black': {"label":"Gold on black","doc":"Gold serif type on an all-black frame, focusing in and leaving with its letters spreading: openings, endings, ceremonies"},
  'title:sticker-bounce': {"label":"Sticker bounce","doc":"White-edged sticker type bouncing in whole and shrinking away: easygoing vlogs, unboxings, food"},
  'title:vhs-corner': {"label":"Tape corner","doc":"Small camcorder on-screen type at the top right, typed in letter by letter: retro, home video"},
  'title:cinema-band': {"label":"Cinema band","doc":"Thin type on a dark band across the frame, letters closing up and spreading apart to leave: travel films, cinematic names"},
  'title:serif-focus': {"label":"Serif focus","doc":"A serif a little spaced, focusing in from a blur: documentary, essay and food film names"},
  'title:spaced-track': {"label":"Wide-spaced name","doc":"Light capitals tracked very wide, closing up and spreading apart to leave: cinematic English names, travel films"},
  'title:stack-left': {"label":"Magazine stack","doc":"A big first line, the lines after it half the size in the highlight colour, set left, rising out of a mask: magazine style, section titles of a list"},
  'title:sign-glitch': {"label":"Neon sign","doc":"Glowing neon tubes on a dark sign board, glitching in: night markets, bars, shop names"},
  'title:vintage-card': {"label":"Vintage card","doc":"Cream old-style serif type on a dark card, rising slowly: old shops, family stories, memories"},
  'title:seal-stamp': {"label":"Double-ruled seal","doc":"A stamp in a double-ruled frame in the accent colour, slightly turned, zooming down onto the frame: certified, verdicts, recommendations"},
  'title:split-open': {"label":"Two-tone split","doc":"The top half of the letters white, the bottom half the highlight colour, opening from the middle and sinking away: sports, streetwear, openings"},
  'title:giant-full': {"label":"Giant word","doc":"The heaviest type, giant, filling the frame's width with a deep soft shadow, focusing in: one word to open, a chapter number"},
  'title:script-lower': {"label":"Script underline","doc":"Handwriting with a stroke of the highlight colour under it, wiped in at the bottom left: vlogs, journal-style places and dates"},
  'title:ribbon-top': {"label":"Ribbon title","doc":"Each line on a notched ribbon in the accent colour, bouncing in at the top: events, celebrations, list titles"},
  'title:chalk-board': {"label":"Chalkboard","doc":"Chalk words on a blackboard in a wooden frame, fading in: lessons, classes, menus"},
  'title:gradient-full': {"label":"Gradient giant","doc":"Big gradient-filled words filling the frame's width, zooming down: openings, countdowns, key numbers"},
  'title:chrome-black': {"label":"Chrome on black","doc":"Chrome metal words on a black frame, focusing in and spreading out: tech, cars, product launches"},
  'title:frost-blur': {"label":"Frosted glass","doc":"The picture blurred behind frosted white words revealed from below: city, coffee, lifestyle chapters"},
  'title:slab-lower': {"label":"Lower slab","doc":"Words on a solid colour slab at the lower left, wiped in and out: names, places, shops"},
  'title:marker-left': {"label":"Highlighter","doc":"Left-aligned words over a highlighter stroke, revealed from below: notes, lessons, list sections"},
  'title:duotone-open': {"label":"Duotone open","doc":"Words in two offset colours, opening from the middle: music, street style, sports"},
  'title:halo-scrim': {"label":"Halo on dark","doc":"The frame darkened, softly glowing words coming into focus: nights, memories, gentle openings"},
  'title:extrude-bounce': {"label":"Extruded bounce","doc":"Thick 3D-looking words bouncing in, shrinking away: games, kids, light-hearted openings"},
  'title:longshadow-top': {"label":"Long shadow","doc":"Flat words with a long diagonal shadow, revealed at the top: explainers, science, how-tos"},
  'title:pixel-top': {"label":"Pixel game","doc":"Pixel words typed out at the top one by one: games, levels, challenges"},
  'title:terminal-left': {"label":"Terminal","doc":"Green terminal text on black, typed out on the left: code, tech, hacker style"},
  'title:rgb-scrim': {"label":"RGB glitch on dark","doc":"Red-and-blue split words glitching in over a darkened frame: electronic music, tech, thrillers"},
  'title:ransom-bounce': {"label":"Ransom note","doc":"Cut-out letters popping in one by one: comedy, mysteries, pranks"},
  'title:tape-top': {"label":"Washi tape","doc":"Words on washi tape at the top, stretching in: crafts, journals, everyday vlogs"},
  'title:postit-left': {"label":"Sticky note","doc":"Words on a sticky note flipping in on the left: to-dos, reminders, study notes"},
  'title:ticket-bottom': {"label":"Ticket stub","doc":"Words on a ticket stub rising at the bottom: travel, films, exhibitions"},
  'title:punch-zoom': {"label":"Punch","doc":"Heavy punchy words slamming down from large: key points, twists, conclusions"},
  'title:credit-bottom': {"label":"Credit line","doc":"A thin, widely spaced line at the bottom whose spacing closes in: crew, end credits, sources"},
  'title:serif-card': {"label":"Serif on a cream card","doc":"Dark serif words on a cream card, rising gently: books, exhibitions, quiet human stories"},
  'title:neon-rules': {"label":"Neon between rules","doc":"Two thin rules drawn first, then neon words light up between them: night views, bars, events"},
  'title:giant-mask': {"label":"Giant reveal","doc":"Huge words filling the frame width, revealed from below and sinking away: chapter numbers, one-word openings"},
  'title:scrapbook-card': {"label":"Scrapbook title card","doc":"Heavy serif words in red-orange on a cream card with double rules above and below and a teal scrap peeking out at its top left, tipped a little: a scrapbook, a trip, a family film."},
  'title:mono-cycle': {"label":"Cycling outline stack","doc":"Wide geometric capitals stacked, one line solid and the others outlined, the solid one stepping down every 0.45 s, glitching in: travel, city and street-fashion titles and chapters (goes with the word frame)."},
  'title:didone-full': {"label":"Magazine giant headline","doc":"Huge high-contrast serif words in dark ink, the first line a small article (THE), the second filling the frame's width (best in English, with the first line shorter than the second), revealed from below: the headline of a city, a landmark or a food feature (goes with the magazine masthead)."},
  'title:storybook': {"label":"Storybook title","doc":"Big mustard serif words with a hard dark shadow at the lower right; a line with no capitals above them (a day / in, simply) is a smaller italic lead-in, and the line under them is small italic: storybook and Wes Anderson-style film names and sections (a day in KYOTO, simply BLOOM.), with common.binocular, common.photostack and the story-serif caption template."},
  'title:story-card': {"label":"Storybook title card","doc":"A whole teal page with a double thin mustard frame, a storybook title inside it (an italic lead-in like and finally,, big serif words, a small italic line like — the last stop —): a title card for the last stop or the next chapter (backColor changes the page, accent the frame)."},
  'title:fin': {"label":"Storybook ending","doc":"An italic mustard fin. on black with a small line under it (the city, the film's name): a storybook ending."},
  'title:pop': {"label":"Dopamine colour blocks","doc":"Heavy serif words on bright flat blocks, side by side and tipped a little: the last line (block) white on the accent colour, the lines before it highlight-coloured on black, a line with no CJK letter in heavy italic Playfair; the kicker a small black block with white words; the letters pop in one by one. Dopamine-colour film titles, sections and endings; accent changes the last block's colour; with common.backdrop's words, common.popcard, common.sticker and the caption template pop-box."},
  'common.flatlay': {"label":"3D desk","doc":"A real 3D desk drawn with three.js: postcards, polaroids, a framed photo, an old TV or a card lie on linen, marble, concrete or velvet under a window's light, the shadow of its frame and leaves swaying gently, with soft shadows and a light depth of field. Each object's picture plays its own shot (silent); objects drop in, slide in and turn over in 3D; the camera pushes in slowly, rises to look straight down, or flies into one picture until it covers the screen. For the sound, or to hand over to the main track after flying in, place that shot lined up with c.flatlayClip. Several objects go in objects (a JSON list, kind picking each one); their x and y are desk units (0 in the table's middle, y up; a 9:16 frame sees ±1.2 × ±2.0, a 16:9 one ±3.0 × ±1.6) and rot is radians (counterclockwise). surface none is a see-through desk over the video."},
  'common.candles': {"label":"Candlestick chart film","doc":"A whole kit for a price-chart film (made for 9:16), by mode: chart, header, tally, card, big. The data is the project's own CSV (data: a file path like media/data/ndx.csv, or the CSV text itself; one line \"date,open,high,low,close\"; a header row and extra columns like Adj Close and Volume are fine; with only \"date,close\" the candles are flat; blank = a made-up sample series). keys, one line \"film second|date|window days or all\", decides which day is drawn at each moment and how many days the frame shows (give chart, header and tally the same set and they always agree); keys and every other second are film seconds, whatever second the item starts at. Give shocks the same seconds in every mode and they shake together on them (the whole frame jumps); updown red = red up green down (Taiwan), green = green up red down; top is the DOM modes' top edge (frame-height fraction, -1 = each mode's own place). Stocks, indices, coin prices, exchange rates, long-run trends, crash retrospectives; sounds: common.thunder, common.impact, common.explode."},
  'common.lens': {"label":"Lens","doc":"A lens that bends the picture itself (the footage and every block and caption on the tracks below bend with it) instead of laying something over it. shape circle, box or full (the whole frame); strength is each look's own amount, and enter / exit grow it from 0 or overshoot and settle. Note: captions under the lens bend too; to keep them sharp, put the lens on a track below the captions. It does not work stacked with a blended block. The preview shows it only in a Chromium browser (Chrome, Edge); the export always uses Chrome. The editor's \"Preview: Smooth\" does not show it either (a mosaic there hides nothing); \"Preview: Full\" and the export do."},
  // block templates (engine templates.ts), keyed <type>#<template id>
  'common.glitch#signal-loss': {"label":"Signal loss","doc":"Surveillance footage, a bad signal, cutting into a memory: fine scan lines and a bright band rolling down, the whole picture jumping sideways more often and farther than look scan alone."},
  'common.glitch#rgb-hit': {"label":"RGB hit","doc":"A musical downbeat, the instant of a scare: every burst pulls the red and blue plates far apart, harder than look rgb alone."},
  'common.glitch#data-break': {"label":"Data break","doc":"Tech, hacking, a system error: many tall rectangles of the picture shoved sideways, tinted cyan and magenta."},
  'common.glitch#soft-tear': {"label":"Soft tear","doc":"A suspenseful build-up, quiet interference: now and then two or three thin colourless inverted bands flash by without stealing the scene."},
  'common.glitch@tear': {"label":"Inverted tear","doc":"Several inverted horizontal bands torn out of the frame (the default): the instant of a transition or a scare; bands is how many, maxHeight how tall at most, and tint tints them cyan / magenta."},
  'common.glitch@scan': {"label":"Scanlines","doc":"Fine scanlines and a bright band rolling slowly down, the whole picture now and then jumping a few px sideways: CCTV, an old TV, a hacker screen."},
  'common.glitch@rgb': {"label":"RGB split","doc":"The red and blue of the picture underneath really split, a faint fringe most of the time and wide apart in a burst: music, beats, a bad signal."},
  'common.glitch@block': {"label":"Block shift","doc":"A few rectangles of the picture underneath displaced sideways, tinted cyan / magenta: corrupt data, a switch, something broken; bands is how many blocks."},
  'common.leak#prism-sweep': {"label":"Rainbow sweep","doc":"Music passages, teenage memories, dreamy transitions: a wide rainbow band sweeps the whole frame from the left, brighter and bigger than usual."},
  'common.leak#bokeh-night': {"label":"Night bokeh","doc":"Night views, night markets, festivals, a warm ending: a field of out-of-focus discs stays on the frame, slowly brightening and dimming, without sweeping."},
  'common.leak#flare-top': {"label":"Top flare","doc":"A cinematic opening, a backlit shot, a sci-fi title: a very bright sideways flare streak held near the top right, its ghost discs lined up to the far side of the frame."},
  'common.leak#warm-corner': {"label":"Warm corner","doc":"Memories, family, a quiet interview: a soft warm glow resting in the top-left corner, barely moving, there for the whole item."},
  'common.leak#sweep-fast': {"label":"Fast sweep","doc":"A transition between two shots: a small, bright warm glow sweeping from the left edge all the way out the right."},
  'common.leak@glow': {"label":"Warm glow","doc":"A big warm glow with a pale core and a rose glow trailing behind (the default): memories, travel albums, a page turn landing, covers, a warm passage at the start or end."},
  'common.leak@prism': {"label":"Rainbow band","doc":"A slanted rainbow band sweeping across (it goes 1.8 times as far as the glow): sun through glass, dreamy, youth, music."},
  'common.leak@bokeh': {"label":"Bokeh","doc":"A dozen or so out-of-focus discs of light drifting slowly and breathing: night scenes, festivals, romance, a warm ending; seed moves them."},
  'common.leak@flare': {"label":"Lens flare","doc":"An anamorphic streak of light stretched sideways through a bright point, with small ghost discs on the line through the frame's centre: cinematic, sci-fi, tech, openings; streak is its colour, blue-white by default."},
  'common.film#super8-home': {"label":"Old home movie","doc":"Childhood, a past generation's home videos, a retro wedding: projected Super 8 home movie film, warmer, grainier and with a heavier vignette than look super8 alone."},
  'common.film#vhs-tape': {"label":"Nineties tape","doc":"Nineties home tapes, a retro vlog, a memory after a tape change: denser scan lines than look vhs alone, warm, and a tracking noise band sliding down soon after the start."},
  'common.film#print-zine': {"label":"Zine print","doc":"Magazine, poster or pop-art passages: the whole picture turned into somewhat coarser print dots, with no vignette."},
  'common.film#cinema-scope': {"label":"Cinemascope","doc":"For 16:9 films: cinematic travel films and title sequences, with 2.39:1 black bars top and bottom, light grain and a soft vignette (on a vertical frame the bars leave only a thin strip)."},
  'common.film#heavy-grain': {"label":"Heavy grain","doc":"Street photography, documentary, raw passages: very coarse, contrasty grain that changes only 12 times a second, like high-speed film stock."},
  'common.film@grain': {"label":"Film grain","doc":"Fine grain plus a soft vignette over the whole frame, nothing more: a light film look, a nostalgic passage."},
  'common.film@vhs': {"label":"VHS","doc":"A home video tape: fixed scanlines, a warm cast, lifted blacks and a vignette, and at the stretches tracking \"second:length:strength\" gives, a tracking-noise band slides down the frame: changing tapes, memories, old video tapes, DV; goes with common.whirr."},
  'common.film@super8': {"label":"Super 8","doc":"Projected Super 8 home movie film: a warm cast, the brightness flickering frame to frame, a heavier vignette and a black gate with rounded corners, vertical scratches coming and going and dust and hairs changing every two frames, the whole gate weaving a little: old home movies, childhood, a past generation's memories, a retro wedding; goes with common.whirr or a projector sound."},
  'common.film@print': {"label":"Print dots","doc":"A printed halftone: the picture becomes a slanted grid of dots, big where it is dark and small where it is light, the colours in dots of their own, on a faint paper tone: magazines, newspapers, clippings, pop art, retro posters; dot is the dot spacing; no vignette; words under it turn to dots too, so keep captions above it."},
  'common.speedlines#manga-focus': {"label":"Manga focus","doc":"Surprise, singling out a person or a thing: dense concentration lines closing in from every edge, leaving a large clear ellipse in the middle for the subject."},
  'common.speedlines#rush-right': {"label":"Rush right","doc":"Running, driving, moving fast: parallel speed streaks across the whole frame flying to the right."},
  'common.speedlines#fall-down': {"label":"Fall down","doc":"Falling, diving, jumping off: long straight streaks across the whole frame flying downward."},
  'common.speedlines#burst-center': {"label":"Center burst","doc":"An entrance, a dash, a big reveal: many long lines radiating from close round the centre, denser and starting nearer the centre than the default."},
  'common.speedlines@radial': {"label":"Radiating","doc":"Comic speed lines radiating outward from one point at (x, y), growing longer and flickering slightly (inner is where they start, length how long): behind a burst card, a moment of surprise or a turn."},
  'common.speedlines@focus': {"label":"Focus lines","doc":"Manga concentration lines: thick ink wedges coming in from every edge toward (x, y) and leaving a clear ellipse round it (inner is its size), shivering: shock, an entrance, a close-up of a face, \"that's him!\"."},
  'common.speedlines@streak': {"label":"Streaks","doc":"Parallel speed streaks of mixed length and weight flying across the whole frame toward angle: a dash, hurrying, fast-forward, the view from a train; white reads best over footage."},
  'common.sparkle#confetti-rain': {"label":"Confetti rain","doc":"Celebrations, awards, birthdays: twice as much coloured paper as mode confetti falls from the top and fills the frame."},
  'common.sparkle#glint-once': {"label":"Single glint","doc":"A product's highlight, jewellery, a sparkling smile: one very large cross flare grows, turns a little and dies, just once."},
  'common.sparkle#star-burst': {"label":"Star burst","doc":"A right answer, a transformation, a level-up: more stars than the default bursting from one point and flying farther."},
  'common.sparkle@burst': {"label":"Star burst","doc":"Four-pointed stars bursting out from one point at (x, y) and scattering (spread is how far they fly): a right answer, a surprise, emphasis."},
  'common.sparkle@twinkle': {"label":"Twinkle","doc":"Four-pointed stars scattered round (x, y) (spread is how far) and twinkling throughout: a premium feel, a dreamy moment."},
  'common.sparkle@confetti': {"label":"Confetti","doc":"Coloured paper pieces falling from the top of the frame over the item, tumbling and swaying, in color and the theme's accent, accent2 and hl (x, y and spread are not used, each count is four pieces): birthdays, prizes, done!, a reveal, parties."},
  'common.sparkle@glint': {"label":"Glint","doc":"One bright point at (x, y) with a long four-way cross flare that grows, turns a little and dies within the item's first second (count and spread are not used): a product, metal, jewellery, a new car, a blade catching the light with a \"ting\"."},
  'common.countdown#flip-clock': {"label":"Flip clock","doc":"A launch countdown, New Year's Eve: a split-flap clock flipping down one card at a time, the last step a number too."},
  'common.countdown#film-leader': {"label":"Film leader","doc":"A retro opening, an old-movie start: a large leader disc almost the frame's width, its hand sweeping a turn each second from 5 down to 0, the last step a number too."},
  'common.countdown#slant-go': {"label":"Slanted GO","doc":"Sports, the start of a challenge: very large slanted numbers with an arc on the right, ending in GO!"},
  'common.countdown#ring-corner': {"label":"Corner timer","doc":"Quizzes, timed tasks: a small ring timer held near the top, out of the way of the picture, the last step a number too."},
  'common.countdown@ring': {"label":"Ring","doc":"A big number bouncing on every tick with a ring around it running out (accent is the ring, ink the number's outline, ring off drops it): quizzes, timed tasks."},
  'common.countdown@slant': {"label":"Slanted","doc":"A heavy slanted number (Anton) with an outlined copy set off behind it and an arc sweeping open on the right over every tick, colors taking turns: a 3-2-1 opening for sport and one-colour fast cuts, with common.grade."},
  'common.countdown@flip': {"label":"Flip clock","doc":"The number on a split-flap card in two halves (the card ink, the number color), the top half flipping down at every tick to show the next number: retro, counting down to an opening, New Year, a launch, \"days to go\"."},
  'common.countdown@leader': {"label":"Film leader","doc":"An old film leader: a disc (color), crosshair lines, a hand sweeping one full turn every tick, the number in the middle (ink), flickering a little with specks of dust, black and white by default: retro openings, nostalgia, home movies, \"the film starts\"."},
  'common.wipe#iris-close': {"label":"Iris close","doc":"The end of a section, a cartoonish change of scene: the picture shrinks into a circle closing to a point in the middle, then opens again from it, like an old cartoon signing off."},
  'common.wipe#blinds-turn': {"label":"Turning blinds","doc":"Business, presentation-like scene changes: 12 narrower horizontal slats turn shut one after another from top to bottom, then turn on round to open."},
  'common.wipe#ink-spread': {"label":"Ink spread","doc":"Culture, ink painting, tea and books: blots of ink spread across the frame and merge, then draw back as if soaked up."},
  'common.wipe#stripes-pop': {"label":"Color stripes","doc":"Trends, outfits, dopamine colors: slanted stripes in four colors sweep in one after another until the last covers the frame, then sweep out."},
  'common.wipe#tiles-collage': {"label":"Collage tiles","doc":"Collage, journals, photo walls turning a page: the frame cut into 6 × 10 small tiles that cover it one by one, then flip open one by one."},
  'common.wipe#band-steep': {"label":"Steep band","doc":"Sports, breaking news: a steeply slanted color band sweeping across from right to left."},
  'common.wipe@band': {"label":"Diagonal band","doc":"A diagonally cut color band sweeping from left to right (dir can reverse it), covering the whole frame at the exact middle moment of the item, a thin line on its leading edge: an everyday scene change or layout switch; color is the band, edge the line's colour and line its thickness."},
  'common.wipe@hand': {"label":"Hand over lens","doc":"A dark, soft-edged palm silhouette with a motion trail slaps up from the lower right, covers the lens completely at the middle of the item, then slides away to the lower left: scene changes, turning away, not wanting to be filmed; hand is the hand's colour."},
  'common.wipe@curl': {"label":"Page turn","doc":"A page turn: the item starts at the cut with the old page covering the frame (a sheet in color, or the still of the outgoing shot (source / t / crop, in win or the whole frame) with a block held at artAt drawn over it (art / artParams, e.g. a common.magazine page, whose video window then holds the still)), and it curls away along angle: the fold sweeps across, the lifted part is the mirrored back (back color, a sheen by the fold, the print showing through faintly) casting a shadow, with a strip of shadow on the new page by the fold: magazine page turns, notebook pages, chapter changes, with common.whoosh; rev plays it backwards (a page laid down, a magazine closing)."},
  'common.wipe@tiles': {"label":"Collage tiles","doc":"The frame cut into cols × rows tiles, paper tiles (color, in two shades) closing one by one until it is all covered at the middle, then flipping open, thin edge-coloured seams between: scrapbooks, collages, photo walls turning a page, with common.slide; keep the seams afterwards with common.scraps' grid."},
  'common.wipe@vortex': {"label":"Word vortex","doc":"Rings of words (words) in bands of color and edge by turns, each ring spinning the other way from its neighbours, the whole slowly zooming in, fading in and out over 0.12 s at its ends and covering the frame between: city, street-fashion and word-frame chapter turns, with common.monoframe."},
  'common.wipe@stripes': {"label":"Color stripes","doc":"Slanted stripes in a few colours sweep across one after another, the last covering the frame at the middle, then sweep away one by one to show the new picture: Dopamine-colour section changes, the last colour the new section's page colour, with common.backdrop's words; colors are the colours (comma-separated), dir left comes in from the right."},
  'common.wipe@iris': {"label":"Iris","doc":"The picture shrinks to a circle as color closes in from outside, down to the point (x, y) at the item's middle with the frame all covered, then opens again from the same point onto the new picture, a thin edge-coloured ring (line thick) on the circle's rim: old films, silent movies, a cartoon's ending and opening, homing in on one person or thing (put x, y there)."},
  'common.wipe@blinds': {"label":"Blinds","doc":"Horizontal slats (rows of them) turn shut one after another from the top, shading as they turn, all shut covering the frame at the middle, then turn on the same way to open: home, indoors, morning, peeking, suspense."},
  'common.wipe@ink': {"label":"Ink spread","doc":"A few color blots with slightly irregular edges (and a few splashed droplets) grow all over the frame and merge, covering it at the middle, then recede from other points as if soaked up, showing the new picture: ink painting, calligraphy, handmade, art, a literary feel; seed moves the blots."},
  'common.rolldoor#shop-close': {"label":"Closing time","doc":"The end of the film, the day's work done: a shutter over the whole frame comes slowly down from 0.2 s (down by 0.8 s later), then the \"Closed today\" sign is taped on."},
  'common.rolldoor#shop-open': {"label":"Opening time","doc":"An opening, a shop opening: the shutter starts closed with an \"open for business\" sign on it (in Chinese) and rolls up from 0.2 s to show the picture."},
  'common.backdrop#halftone-pop': {"label":"Pop halftone","doc":"Pop art, comics, a sporty feel: denser, stronger halftone dots than the halftone pattern alone, largest at the lower left and shrinking toward the upper right."},
  'common.backdrop#sunburst-show': {"label":"Show sunburst","doc":"Prize draws, announcements, a variety-show feel: wide two-color rays from the middle, slowly turning."},
  'common.backdrop#waves-summer': {"label":"Summer waves","doc":"Beaches, summer, easygoing passages: four layers of larger waves stacked from the bottom, each sliding sideways at its own pace."},
  'common.backdrop#spot-quote': {"label":"Quote spotlight","doc":"Quotes, interviews, podcasts: a near-black blue-grey ground with a stronger soft light from the top edge, darkening below and in the corners."},
  'common.backdrop#dots-party': {"label":"Party dots","doc":"Cute, celebrations, children: larger, stronger dots slowly sliding, with small twinkling bits scattered along both sides."},
  'common.backdrop@gingham': {"label":"Gingham","doc":"Gingham checks of wide color2 bands crossing both ways (tint is the strength, scale the check size): a cute, homely, handmade section ground."},
  'common.backdrop@dots': {"label":"Dots","doc":"Neat rows of small color2 polka dots (tint is the strength, scale the spacing): cute, celebrations, children."},
  'common.backdrop@stripes': {"label":"Stripes","doc":"Diagonal color2 stripes at 45°, one filled and one clear (tint is the strength, scale one pair's width): a lively section ground with a beat."},
  'common.backdrop@grid': {"label":"Grid","doc":"Graph paper of thin color2 lines (tint is the strength, scale the square size): tutorials, notes, an informative ground."},
  'common.backdrop@solid': {"label":"Solid","doc":"One plain colour, color, with no pattern: when you want a clean ground, or only glow, pool or bits."},
  'common.backdrop@gradient': {"label":"Gradient","doc":"A gradient running at a slant from color at the top to color2 at the bottom, with no pattern: a soft, clean ground for openers, end cards or panels."},
  'common.backdrop@diamond': {"label":"Diamond","doc":"The diamond pattern of a cash-register mat (thin crossing color2 lines); pool adds a ring of warm light and vignette darkens the corners: dark counters, workbenches."},
  'common.backdrop@spot': {"label":"Spotlight","doc":"A dark poster ground: a soft light falls from the top edge (color2, density tint) and it fades darker below: quotes, interviews, podcasts."},
  'common.backdrop@words': {"label":"Word wall","doc":"A Dopamine word wall: the page filled with rows of word (outlined heavy serif in color2 at tint, rows scale high), neighbouring rows sliding opposite ways at drift; section colours change often (lime, cobalt, hot pink, orange), with common.popcard, common.sticker and the title template pop."},
  'common.backdrop@halftone': {"label":"Halftone","doc":"A dot screen: rows of dots at 45° (color2 at tint, scale apart), biggest at the bottom left and shrinking to nothing at the top right: pop art, comics, retro print, a sporty ground."},
  'common.backdrop@sunburst': {"label":"Sunburst","doc":"Two-colour rays from the frame's centre (color2 at tint), turning slowly: prize draws, announcements, sales, retro posters, variety shows; a bigger scale gives fewer, wider rays, drift is the speed (a tenth of a degree a second), and it turns only with a drift, 40 is a good one."},
  'common.backdrop@waves': {"label":"Waves","doc":"Four layered wavy bands rising from the bottom (color2, stronger lower down), each sliding sideways at its own speed: the seaside, summer, relaxed, fresh, music; scale is the waves' size, and they move only with a drift, 40 is a good one."},
  'common.shader#neuro-tech': {"label":"Tech web","doc":"Tech, AI, data: a glowing web of thin lines on a dark ground, flowing more slowly than look neuro alone."},
  'common.shader#cells-glass': {"label":"Stained glass","doc":"Handmade, stained glass, art: more irregular colored cells than look cells alone, slowly squirming."},
  'common.shader#dither-retro': {"label":"Retro dither","doc":"Retro games, electronic music: larger dither dots drawing broad flowing shapes, like an old one-color computer screen."},
  'common.shader#smoke-slow': {"label":"Calm smoke","doc":"Brands, calm passages: a smoke ring enlarged past the frame's edges, so smoke fills the whole picture around a dark middle; calmer than look smoke alone, slowly drifting."},
  'common.shader#rays-stage': {"label":"Stage rays","doc":"Stages, announcements, award ceremonies: stronger rays than look rays alone, shining down from above."},
  'common.shader@mesh': {"label":"Mesh gradient","doc":"A soft gradient of a few colours flowing slowly and bleeding into each other like paint: openers, end cards, a brand-like ground; a bigger amount warps it more, and grain adds a layer of grain."},
  'common.shader@grain': {"label":"Grainy gradient","doc":"Coloured gradients with coarse grain welling up from the corners of a back-coloured ground, slowly changing shape: a textured opener, a section without footage; grain 0 uses its own grain of 0.25."},
  'common.shader@rays': {"label":"Light rays","doc":"Beams of light fanning down from a point above, with a glow, on a back-coloured ground: stages, announcements, award ceremonies."},
  'common.shader@smoke': {"label":"Smoke ring","doc":"A ring of coloured smoke in the middle of a back-coloured ground, wisps drifting off its edges: brands, calm sections."},
  'common.shader@warp': {"label":"Warped checks","doc":"Checks twisted and pulled into flowing marbled patches filling the frame (back is not used): a busy, psychedelic opener or section ground."},
  'common.shader@swirl': {"label":"Swirl","doc":"Wide bands of the colours and back turning out from the centre in a swirl: a retro, psychedelic opener; grain 0 uses its own grain of 0.2."},
  'common.shader@blobs': {"label":"Fluid blobs","doc":"A few coloured fluid blobs melting together and slowly changing shape on a back-coloured ground: a simple opener or end card; a bigger amount gives more blobs."},
  'common.shader@dots': {"label":"Dot orbits","doc":"A back-coloured ground full of small coloured dots, each circling its own orbit: a busy, party-like section ground; a bigger amount spreads them wider."},
  'common.shader@neuro': {"label":"Neural web","doc":"A flowing web of thin glowing lines on a dark ground, brightest where they cross: tech, AI, neural networks, late night, suspense; the first colour is the lines, the last the hot points, and amount brightens the crossings."},
  'common.shader@cells': {"label":"Cells","doc":"Irregular patches of colour like living cells or stained glass, slowly squirming, with thin gaps in back between them: nature, biology, collage, a lively info ground; amount makes the cells more uneven, grain shades each one inwards."},
  'common.shader@dither': {"label":"Retro dither","doc":"Retro dot dithering in two colours only, the first colour and back, an ordered dot pattern drawing a flowing warp like the one-bit screen of an old computer or handheld console: retro, pixels, games, hackers, lo-fi; amount is the dot size."},
  'core.flash#bloom-pop': {"label":"Bloom flash","doc":"A beat, a camera flash: a glow from the middle fills the frame at once, then shrinks back to a point within half a second."},
  'core.flash#fade-in': {"label":"White fade-in","doc":"An opening, waking from a memory: the frame starts all white, thins over the whole item to a glow in the middle, and the glow shrinks away to show the picture."},
  'core.flash#fade-out': {"label":"Fade to black","doc":"An ending, the close of a part: black covers the frame slowly over the whole item, all black at the end."},
  'core.flash#soft-dip': {"label":"Soft light dip","doc":"A gentle change of part: the frame only brightens (screen), rising in 0.15 s, holding a moment, then easing back."},
  'core.flash@flat': {"label":"Flat flash","doc":"One even colour over the whole frame, rising and falling with the curve: the flash of a retake, a transition or a camera shutter, or a whole-item fade in or out with fade."},
  'core.flash@bloom': {"label":"Bloom","doc":"A glow spreading from one point (x, y), growing until it fills the frame: the light at the end of a tunnel, memories, endings."},
  'core.flash@glow': {"label":"Glow","doc":"A patch of light held at (x, y), its size fixed (size) and only its strength following the curve, never covering the frame: the gold light of a celebration, a spotlight; with blend normal it shows on bright footage too."},
  'common.grade#bw-to-color': {"label":"Black and white to colour","doc":"Back from a memory to now: all black and white at first, the colours coming back at once at 0.6 s."},
  'common.grade#mono-punch': {"label":"Mono punch","doc":"Stressing one moment: in its own colours, then from 0.3 s all one deep colour (deepened), back to its colours at 0.9 s."},
  'common.grade#bw-hold': {"label":"All black and white","doc":"A memory, a documentary or a serious part: black and white for the whole item."},
  'common.grade#sepia': {"label":"Old-time brown","doc":"Old streets, old photos, nostalgia: all one deepened brown, the bright parts toward beige."},
  'common.lens#spot-zoom': {"label":"Spot zoom","doc":"Pointing out something small in the picture (a price, the words on a sign, a little thing in a hand): a round magnifier smaller than the default with a thin white rim, popping in past full size and settling, 2.5 times inside; it sits at the lower left, so move x and y onto the thing."},
  'common.lens#scan-glass': {"label":"Scanning glass","doc":"Searching, inspecting, a close look: a round magnifier with a white rim and a glass gleam sweeps across the frame from left to right over the whole item, doubling whatever it passes; move y to the row to scan."},
  'common.lens#censor': {"label":"Censor mosaic","doc":"Hiding what must not be seen (a passer-by's face, a number plate, a logo): a square mosaic of the biggest cells (6% of the frame's short side) that stays put, with no entrance or exit, the same from start to end; move x, y and size onto what to hide."},
  'common.lens#pixel-cut': {"label":"Pixel cut","doc":"A transition to a new topic or section: the whole frame turns to mosaic, its cells growing and then shrinking again. Make the item 0.5–0.8 s long and place it across the cut (half over the end of one shot, half over the start of the next), so the biggest cells cover the frame where the shot changes."},
  'common.lens#heat-haze': {"label":"Heat haze","doc":"Heat, dizziness, a dream, under water: the whole frame wavers gently, waves lying sideways drifting slowly upward, fading in and out at the ends; it can run long."},
  'common.progress#dog': {"label":"Dog run","doc":"Pets, walks, easy-going vlogs: a little dog hops to the right along a track at the bottom of the frame, the part behind it filled in, and the flag at the finish bounces when it gets there; set runner to another emoji for another character."},
  'common.progress#sausage': {"label":"Sausage dog","doc":"Pets, family, anything cute: a hand-drawn dachshund at the bottom of the frame whose body is the progress bar and grows longer as it goes, tail wagging all the way, tongue out at the finish; set look to cat or worm for another animal."},
  'common.progress#paws': {"label":"Paw trail","doc":"Pets, walks, on the road: twelve paw prints stamped one by one along the top edge, left and right feet alternating, the newest the brightest."},
  'common.progress#fuse': {"label":"Burning fuse","doc":"Hook shorts, suspense, countdowns: a spark burns along a rope at the bottom of the frame towards a bomb, leaving ash behind, and the bomb jumps when it gets there; reveal the answer at that moment."},
  'common.progress#battery': {"label":"Charging","doc":"Unboxings, challenges, workouts, a day out: a battery in the lower left charges cell by cell, the percentage beside it counting up, and it changes colour and blinks twice when full."},
  'common.progress#rocket': {"label":"Rocket launch","doc":"Launches, growth, challenges, goals reached: a rocket against the left edge of the frame (the right is where short-video apps put their buttons) climbs from the bottom trailing a flame, the track behind it filled in, and the moon at the top bounces among fireworks when it gets there; set runner to a balloon and it floats up instead."},
  'common.progress#vine': {"label":"Flowering vine","doc":"Gardening, cooking, growing up, family: a hand-drawn vine grows to the right along the bottom of the frame, putting out leaves on the way, and its bud opens into a flower at the end; set goal to a strawberry and it bears fruit instead."},
  'common.progress#stamps': {"label":"Stamp card","doc":"Challenges, check-ins, list videos: a small paper card in the lower right gets a star stamp for each chapter done, and when it is full the whole card hops and the stamps change colour; dots is the number of cells, runner swaps the stamp."},
  'common.progress@bar': {"label":"Bar","doc":"A progress bar along the top or bottom of the safe zone, filling from left to right with the film: for a plain, quiet progress line."},
  'common.progress@dots': {"label":"Chapter dots","doc":"A row of chapter dots along the top or bottom of the safe zone, the ones reached filled and the current one bigger; dots is how many, and icons turns them into a row of emoji (a dish a stop, say)."},
  'common.progress@tabs': {"label":"Chapter tabs","doc":"A row of chapter tabs along the top or bottom of the safe zone (icon + chapter name, finished ones ticked, the current one lights up and bounces); labels are the names, icons the icons before them: recipes, tutorials, anything in steps."},
  'common.progress@pencil': {"label":"Pencil steps","doc":"A handwritten title with a red line on the left, and \"Step 3/8\" (counterSize sets its size) with a row of hand-drawn circles on the right (the current one filled red, finished ones ticked): recipes and tutorials, step by step."},
  'common.progress@timeline': {"label":"Timeline","doc":"A thin line through evenly spaced dates (labels), a glowing dot sliding from stop from to stop step, the big date and the place (place) written under the line; step -1 draws the whole line out and writes \"first day — last day\" (the ending): travel diaries, stop by stop."},
  'common.progress@slots': {"label":"Numbered cards","doc":"A row of numbered cards, empty dashed ones (01 02 03) that turn into filled cards as each point is made (fills), the number on an accent block and the keyword beside it (labels); pulses make a card hop and glow again later (a recap), and common.slip's slot flies a big card into one of them: three rules, three reasons, list-style podcast clips."},
  'common.progress@osd': {"label":"Camcorder to-do","doc":"A camcorder-OSD to-do counter: VT323 pixel type with a VHS red/cyan fringe, \"TO-DO 3/6\" (title is the word before the count) over a row of boxes that tick at the fills seconds (in the done colour), the item just ticked (labels) typed under them for hold seconds, the count blinking when all are done; on the right safe edge (align left: the left), goes with common.camcorder and common.ding: a day's to-dos in a retro camcorder vlog."},
  'common.progress@runner': {"label":"Runner","doc":"A character (runner, a dog by default) hopping to the right along a track to the goal (a flag by default); either can be any emoji or a picture in the project (a plane or a car for travel, a dog or a cat for pets)."},
  'common.progress@stretch': {"label":"Long dog","doc":"A hand-drawn dachshund whose body is the bar and grows longer, its tail wagging, its tongue out on arrival (look cat or worm; the coat is tan, #c98a4b, unless color gives another): pets, family, anything cute."},
  'common.progress@paws': {"label":"Paw prints","doc":"Paw prints stamped one by one (dots is how many, 12 reads well; runner swaps the stamp for an emoji): pets, walks, on the road."},
  'common.progress@segments': {"label":"Segmented bar","doc":"A stories bar with one segment a chapter, the current one filling (dots the number, at the start of each in seconds): a film in chapters."},
  'common.progress@fuse': {"label":"Fuse","doc":"A spark burning along a rope to the goal (a bomb by default; color #ffb300): countdowns, hooks, suspense."},
  'common.progress@battery': {"label":"Battery","doc":"A battery in a corner charging cell by cell with a percentage beside it, red under 20%, turning the done colour and blinking twice when full (the lit cells are green, #34c759, unless color gives another; align left puts it on the left): unboxings, challenges, workouts, a day out."},
  'common.progress@rocket': {"label":"Rocket","doc":"Upright against the left or right edge and as tall as the safe area: a rocket trailing a flame climbs to the goal at the top (a moon by default), which bounces among fireworks when it gets there (align left for the left edge, otherwise the right; position and y do nothing; set runner to a balloon or anything else that goes up; it runs the whole height of the frame's edge, so move it to the other side or lower iconSize if wide captions touch it; on vertical shorts keep it on the left, clear of the app buttons on the right): launches, growth, challenges, goals reached."},
  'common.progress@ring': {"label":"Ring","doc":"A ring in a corner drawn round as it goes with the percentage in its middle, turning the done colour with a little pop when full (size is its size, align left puts it on the left; a runner emoji sits in the middle instead of the percentage): fits anything."},
  'common.progress@vine': {"label":"Vine","doc":"A hand-drawn vine growing to the right along the edge, putting out leaves, and a flower opening at the end (a green vine, #4caf50, with pink petals, #ff8fb1, unless color gives the stem and leaves another and done the petals; a goal emoji is what it bears, such as a strawberry): gardening, cooking, growing up, family."},
  'common.progress@stamps': {"label":"Stamp card","doc":"A small paper card in a corner stamped once for each chapter done (dots the number of cells, two rows above six), the whole card hopping and the stamps turning the done colour when it is full (runner swaps the stamp, a star for one; align left puts it on the left): challenges, check-ins, lists."},
  'common.lens#whip': {"label":"Whip","doc":"A fast change of scene, a head turn, looking the other way: the whole frame smears sideways into streaks for an instant and comes back sharp. Make the item 0.3–0.5 s long and place it across the cut, so the shot changes at the fullest blur."},
  'common.lens@magnify': {"label":"Magnifier","doc":"A magnifier, 1–2.5 times inside the lens: point at something small in the frame; with travel it sweeps the frame, searching."},
  'common.lens@fisheye': {"label":"Fisheye","doc":"A fisheye: the middle bulges and the rim is squeezed: comic, exaggerated, a close look."},
  'common.lens@mosaic': {"label":"Mosaic","doc":"A mosaic of square cells up to 6% of the short side: hide what must not be seen; shape full with enter and exit grow is a pixelate transition."},
  'common.lens@ripple': {"label":"Ripple","doc":"Water or heat haze: the picture wavers and the waves flow one way: heat, dizziness, dreams, under water; speed sets the flow, axis the waves' direction."},
  'common.lens@streak': {"label":"Streak","doc":"A one-way blur pulling the picture into lines across or down: a whip pan, a fast change of scene; axis sets the way."},
  'common.lens@prism': {"label":"Prism","doc":"Red and cyan part more and more toward the edge while the middle stays sharp: dreamy, dazed, techy."},
  'common.badge@star': {"label":"Star","doc":"A yellow five-pointed star with a dark outline, the number tilted in its middle, the plate in bold words over a highlighter stroke (plateColor): rankings, lists."},
  'common.badge@burst': {"label":"Burst","doc":"A jagged badge ringed with spikes like a burst sticker, the number in its middle, the plate in highlighted words as with the star: livelier lists, which shop."},
  'common.badge@circle': {"label":"Circle","doc":"A round badge with a dark outline, the number in its middle, the plate in highlighted words as well: plainer section intros, which tip."},
  'common.badge@box': {"label":"Tilted box","doc":"A slightly tilted flat block (color ground, textColor words, heavy italic; the font Playfair Display looks most like a magazine), its plate a small block of the same colour, x its left edge: Dopamine-colour lists, with common.popcard."},
  'common.tag@pill': {"label":"Pills","doc":"A row of small pill tags (coloured c1, c2, c3 in turn) popping in one after another: small key points under a title, such as certification, type, price, distance."},
  'common.tag@label': {"label":"Place and date","doc":"A location + date label of joined blocks (dark ground with white text and an accent edge, highlighter-coloured date) that wipes in from the left within one beat: arriving somewhere in a travel film, naming the place and the date."},
  'common.tag@tape': {"label":"Paper tape","doc":"A paper-tape label: each tag handwritten on its own strip of cream paper tape with a highlighter stroke growing under the words, no circled in red pen at the left of the first strip (a shop or stop number), the strips landing with a little bounce: notebooks, planners, walking maps."},
  'common.tag@pin': {"label":"Map pin","doc":"A pin label: a teardrop map pin drops onto x, y (its tip) with a label card above it (the first tag, the second a small line under it); check ticks the pin's head at that second: maps, places visited, sights."},
  'common.tag@glass': {"label":"Frosted glass","doc":"Frosted glass tags appearing one after another (step is the gap); stack puts them in a column, and check ticks each one in the accent colour that many seconds after it appears: brand films, a checklist, things done."},
  'common.tag@day': {"label":"Planner date","doc":"A planner date label: a torn paper slip at x, y with tape on its corner, the first tag in a big italic serif (Day 2, 07:30) underlined in pen, the second handwritten under it (the weather, a place), popping in with a turn: the day of a vlog, a timeline of a day, a travel diary."},
  'common.tag@ember': {"label":"Ember brand","doc":"A charcoal-fire dish label: a charcoal plate slides in from the left with a glowing c1 bar on its edge, the first tag's letters branded on one by one like a hot iron (flaring in c1, cooling to the paper colour), the second tag a small line under it; it was made at size 3.2 (the default 1.8 suits the pills): barbecue, grilled dishes, a dish or a place name."},
  'common.header@chip': {"label":"Number chip","doc":"A numbered colour block plus a title at the top of the frame (01 Intro, Step 2...), sliding in from the left: everyday chapters and steps."},
  'common.header@kicker': {"label":"Kicker","doc":"A heading that stays up for a whole section: a main-colour dot with small grey text above (the show name; kickerSize sets its size), and a bold title line below wiping open from the left, a 【word】 turning main-coloured; when it does not fit, the small text shrinks and the title wraps, both kept within the side safe margins: what this film asks, in interviews, podcasts, reviews."},
  'common.header@slate': {"label":"Clapperboard","doc":"A small corner label: a clapperboard dropping in and its arm snapping shut, the number and title on it (pair with common.thud): a chapter opening that feels like a film set."},
  'common.header@flip': {"label":"Split-flap","doc":"A small corner label: a split-flap board whose cells flip one by one to the number, then the title plate opens (common.tick): travel, setting off, the next stop."},
  'common.header@side': {"label":"Bookmark","doc":"A small corner label: an upright bookmark at the left edge, the number on a colour block above the title set vertically (a long one shrinks, then is cut; common.whoosh): a chapter mark that keeps the middle of the frame clear."},
  'common.header@big': {"label":"Big number","doc":"A small corner label: a huge outlined number rising from its bottom edge with the title over its lower part (common.whoosh): a chapter opening with a magazine-page feel."},
  'common.burst@sticker': {"label":"Sticker","doc":"One big word inside a jagged burst shape (pops in, slightly tilted; points is the number of spikes): a sticker-like burst word such as \"Let's go!\" or \"So tasty!\"; shadow given a colour is a coloured shadow offset to the lower right, dots given a colour is halftone dots over the fill (a comic burst balloon, with common.comic)."},
  'common.burst@blast': {"label":"Full-frame blast","doc":"The whole frame bursts open: a white flash, rotating rays, a pulsing red vignette, a huge word with a double outline: off the charts, record broken, the big reveal."},
  'common.burst@rays': {"label":"Ray burst","doc":"The moment of a bite: a ring of thin rays shoots out from (x,y) and a big word (\"Crunch!\") springs back from large to size at (tx,ty), tilted: bite, knock, smash, juice squirt."},
  'common.burst@cloud': {"label":"Cloud","doc":"One big word inside a puffy cloud (fill the fill, ink the outline; points is the number of bumps, seed changes their sizes), popping in softly and wobbling a little before it settles: cute, happy words like \"Yum\" or \"Yay\"; shadow and dots as for sticker."},
  'common.burst@star': {"label":"Star stamp","doc":"A word inside a fat five-pointed star with rounded corners, turning a quarter turn as it grows and settling (fill the fill, ink the outline; keep the word short to fit): ratings, a win, \"No.1\", \"recommended\"; shadow and dots as for sticker."},
  'common.burst@splat': {"label":"Paint splat","doc":"A splat of paint in the fill colour (its shape from seed, no outline) with a few drips running down and small drops thrown out, the word in textColor (switched to black or white when it is too close to the fill), smacked in from small with the drops flying out a moment later: messy, loud, \"oh no\", \"spoiler\"."},
  'common.quote@words': {"label":"Word by word","doc":"A dynamic quote: the video shrinks into a small window at the upper right (win), a big opening quotation mark and the speaker at the left, below it the lines jump out word by word on the speaking time (times; evenly spread if not given), the hit line is enlarged and slammed down, the whole thing shakes once, a main-color light flashes and the earlier lines dim; pre puts some lines up first as dark teaser text, ghost lets that line appear faintly first (an opening teaser); sizes and serif set each line's size and serif face."},
  'common.quote@card': {"label":"Closing card","doc":"An opaque closing quote card (bg its ground): a big quotation mark, the lines floating up one by one (the hit line in the main color, earlier ones gray), a short line and the source (who), a line of small text at the bottom (kicker); sizes and serif set each line's size and serif face."},
  'common.quote@type': {"label":"Typewriter","doc":"A typewriter: the quote as a left-aligned block in the middle of the frame, every character in a cell of the same width, typed out one by one (done at about 60 % of the item), a main-color block cursor after the last character, steady while typing and blinking after; a 【word】 (else the hit line) in the main color, kicker above, who below once it is typed, y the first line's top (-1 = centred): confessions, chat-like lines, definitions."},
  'common.quote@block': {"label":"Stacked block","doc":"Big stacked type: every line sized to one width (short lines huge, long ones small) and stacked tight into one solid block, the lines landing one after another; a 【word】 (else the hit line) in the main color, a line's closing Chinese comma or full stop dropped, kicker above, who below at the end, y the first line's top (-1 = centred): manifestos, slogans, an opening line where the words are the picture."},
  'common.slam@plain': {"label":"Outlined","doc":"Big outlined words (color the fill, outline the stroke, shadow given a colour an offset shadow): any key line."},
  'common.slam@led': {"label":"LED sign","doc":"Glowing red text in a black LED sign (ledColor changes it) under a grid of dark dots: a frozen confession."},
  'common.slam@gold': {"label":"Champagne gold","doc":"Big italic serif words in a champagne-gold gradient with a dark soft glow and a warm flash as they land: a shout, a wish, a name."},
  'common.slam@neon': {"label":"Neon","doc":"Near-white tube letters in layered glows of hl, a 【word】 a second cyan tube, each line flickering a few times before it lights and then breathing softly (no pop, no shake; stagger lights the lines one after another): night scenes, bars, the city, \"open now\"."},
  'common.slam@extrude': {"label":"3D block","doc":"Retro 3D block letters: a color face, a thin outline and a stack of hard shadows stepping down to the right (shadow given a colour colours the side): titles, game-show energy, big claims."},
  'common.slam@box': {"label":"Label blocks","doc":"Each line on its own solid block in the outline colour, tipped a little one way then the other, sliding in from alternate sides one after another (stagger sets the gap, shadow gives the blocks a hard shadow); a magazine cut-out feel: lists of claims, steps, strong lines over busy footage."},
  'common.slam@split': {"label":"Colour split","doc":"Words in color with two misregistered colour plates (hl and cyan) behind them, jumping about for some 0.3 s as they land and then settling slightly off: tech, glitches, errors, \"wait, what?\"."},
  'common.strike@marker': {"label":"Two marker strokes","doc":"Two thick marker strokes slanting across the line from the left (the second steeper): any \"actually, no\"."},
  'common.strike@scribble': {"label":"Scribble","doc":"A tight back-and-forth zigzag scribbled over the whole line from the left in about 0.3 s: angrily crossed out, a slip of the tongue, taking it back."},
  'common.strike@cross': {"label":"Big X","doc":"A big hand-drawn X, two slightly wobbly strokes from corner to corner over the line: wrong, a no-go, never do this."},
  'common.strike@bar': {"label":"Redacted","doc":"A solid bar in the accent colour wiped across the line from the left until it is covered, like a redacted document: things that can't be said, censorship, a cancelled plan."},
  'common.onomatopoeia@pop': {"label":"Pop","doc":"Coloured letters with a heavy ink outline popping in one by one, each tipped a little the other way and twitching while it stays (depth adds a hard ink shadow): a laugh, a sniff, any sound word."},
  'common.onomatopoeia@shout': {"label":"Shout","doc":"Each letter bigger than the last, slammed down from huge, a color2 rim outside the ink outline and a hard shadow, shaking hard all the while: a yell, a boom, a scream, a fright."},
  'common.onomatopoeia@tremble': {"label":"Shiver","doc":"Thin-outlined letters in color2 with a ghost in color on either side, every letter shaking and tipping without rest: cold, fear, nerves, a phone buzzing."},
  'common.onomatopoeia@whisper': {"label":"Whisper","doc":"Thin letters with no outline, spaced wide inside a soft dark glow, fading in slowly one by one and drifting up: silence, Zzz, an awkward pause, a thought."},
  'common.onomatopoeia@zoom': {"label":"Whoosh","doc":"Forward-leaning letters shot in from the left, trailing ghosts in color and a few speed streaks in color2: a whoosh, a swish, a dash, something flying past."},
  'common.onomatopoeia@rumble': {"label":"Rumble","doc":"Letters in the ink colour with a thin rim and glow in color, dropped from above, squashed by the landing, then rumbling slow and heavy: thunder, a thud, a quake, menace."},
  'common.onomatopoeia@sparkle': {"label":"Sparkle","doc":"Letters shading from color2 at the top to color, a white rim and a soft glow, spinning open with four-pointed glints twinkling around them: shiny, an entrance, done, so pretty."},
  'common.onomatopoeia@bubble': {"label":"Squishy","doc":"Rounded letters in a thick color2 rim hopping one after another like jelly, stretching on the way up and squashing on the way down: a kiss, a pop, munching, anything soft or cute."},
  'common.onomatopoeia@halftone': {"label":"Halftone","doc":"Pop-art comic letters: color2 dots over color, a heavy ink outline and a hard shadow down to the right, the whole word banged in at once: POW, BAM, a hit, a crash."},
  'common.handwrite@pen': {"label":"Fountain pen","doc":"Thin ink-coloured fountain-pen letters written one by one, with a glow of the note paper colour behind them so they read over video too: captions, postcards, diaries, planners."},
  'common.handwrite@chalk': {"label":"Chalk","doc":"Rough, grainy chalk letters, a little uneven in strength, written in the note paper colour with a faint dust behind them; on a dark picture they look like a blackboard (with paper: note the note becomes a little board in the color ink colour): recipes, lessons, menus."},
  'common.handwrite@marker': {"label":"Highlighter","doc":"Behind each line as it is written, a slightly tilted, translucent highlighter band with ragged ends follows the pen, the words still in the color ink: key facts, notes, study vlogs; only it reads hl (the highlighter colour)."},
  'common.handwrite@crayon': {"label":"Crayon","doc":"Thick crayon letters with broken, waxy edges, each sentence in the next crayon: the first in color, then blue, green, orange and purple in turn (a fixed set of crayon colours): kids, family, playful diaries."},
  'common.dotmatrix@still': {"label":"Still","doc":"Still dot-matrix text on a board as wide as the words, at most w, the dots shrinking when it does not fit: signs, LED boards."},
  'common.dotmatrix@marquee': {"label":"Marquee","doc":"A marquee scrolling from right to left through a board w wide (speed is how fast): marquees, LED boards."},
  'common.dotmatrix@type': {"label":"Typed","doc":"Typed out character by character (typeDur is how long it takes); with look print it is like a receipt printing: receipts, queue displays."},
  'common.headline@doc': {"label":"Documentary card","doc":"A documentary-style title card: a big serif headline (several lines allowed) with a line of small text, two thin rules growing out from the middle above and below, the whole card rising in and fading out at the end; bg band is a dark band behind the text, black turns the whole frame black (a serious card, chapters, years, places), none only the text and its shadow; type types the letters in one by one, enter roll unrolls each character from narrow to full width like dough; strikeFrom + strikeAt run a thin line through the words from that character on at that time and fade them (no additives, what we used to think): chapter openings in history, documentary, essay, travel and brand films."},
  'common.headline@brand': {"label":"Brand line","doc":"Brand-film words: lines resolving one by one from a blur at the bottom left, the small text (sub) becoming a small heading above them, y the baseline of the last line (-1: the bottom of the safe area): a brand film's line, what we do."},
  'common.headline@proof': {"label":"Proof number","doc":"A brand film's proof: a big number counting up on the left (text, for example 90+), the small text (sub) a letter-spaced label under it; a text that is not a number resolves from a blur line by line at the brand size: a brand film showing how much it has done."},
  'common.headline@name': {"label":"Name title","doc":"A big italic serif name (text; Chinese, Japanese and Korean characters stay upright) rising in letter by letter with one shimmer of light, a gold rule drawing out both ways from a dot in its middle under it and a letter-spaced line (sub, for example SWEET SIXTEEN): the name title of a birthday, wedding or graduation."},
  'common.stamp@box': {"label":"Box stamp","doc":"A boxed bold-text stamp that grows first, then drops onto the frame, slightly tilted: a verdict of a word or two."},
  'common.stamp@circle': {"label":"Round stamp","doc":"A double-ring round stamp, the word centred in rings a little wider than it, dropping like box: a verdict or a recommendation that should look like a real seal."},
  'common.stamp@card': {"label":"Stance card","doc":"A sticker-like stance card: a solid main-color card with thick white text (up to two lines; a 【word】 turns hl-colored), a black border with a hard shadow and a small tag at the side, dropping in from 1.35x; anchor sticks the card's top or bottom edge to y: one person's stance or a key line in a conversation or debate."},
  'common.stamp@double': {"label":"Verdict seal","doc":"A verdict seal: a double-ruled rounded frame on a translucent paper ground (paper) with a soft shadow, dropping like box: verdict, rejected, case closed, certified."},
  'common.stamp@ember': {"label":"Branded verdict","doc":"A branded verdict: a big italic serif word on a charcoal plate (ink) with faint diagonal stripes and an inner rule in color, slammed down from 1.45x, glowing in color like a hot iron and cooling to paper within a second: barbecue, grilling, delicious, a verdict."},
  'common.pen@circle': {"label":"Circle","doc":"A hand-drawn loop round something, its end running a little past the start: circling a key spot or a product in the frame."},
  'common.pen@arrow': {"label":"Arrow","doc":"A curved line drawn from lower left to upper right, its head added last: pointing at something in the frame."},
  'common.pen@underline': {"label":"Wavy underline","doc":"A wavy line going up and down (give h a small value, such as 0.04): under a word or a product, for emphasis."},
  'common.pen@check': {"label":"Check","doc":"A check mark: done, right, an item ticked off a list."},
  'common.pen@cross': {"label":"Cross","doc":"A cross in two strokes: wrong, don't do this."},
  'common.pen@heart': {"label":"Heart","doc":"A heart, filled with the pen's colour when filled is on: love it, recommended."},
  'common.pen@star': {"label":"Star","doc":"A five-pointed star, filled with fill when filled is on: a key point, a favourite."},
  'common.pen@stars': {"label":"Star burst","doc":"A ring of little stars and hearts bursting out from the middle, swaying and pulsing a little: a surprise, something cute, joy."},
  'common.pen@burst': {"label":"Spiky halo","doc":"A spiky halo that swells a little as it is finished: emphasis, \"this is amazing\"."},
  'common.pen@rays': {"label":"Surprise lines","doc":"Five short lines fanned out above, like the surprise lines over a comic character's head: surprise, a discovery."},
  'common.pen@steam': {"label":"Steam","doc":"Three curling wisps of steam rising and fading over and over: food served hot."},
  'common.pen@clock': {"label":"Clock","doc":"A filled alarm clock (two little bells on top) whose hands turn: time, waiting, how long it took."},
  'common.pen@house': {"label":"House","doc":"A little house (roof, chimney, door, window) with a small heart drifting from the chimney once it is drawn: home, going home, where someone lives."},
  'common.pen@snow': {"label":"Snowflake","doc":"A six-armed snowflake turning slowly: cold, winter, something icy."},
  'common.pen@diamond': {"label":"Diamond","doc":"A diamond filled with fill, two little cross glints twinkling beside it: precious, luxury."},
  'common.pen@qmark': {"label":"Question mark","doc":"A handwritten question mark: a question, \"why?\"."},
  'common.pen@thumb': {"label":"Thumbs up","doc":"A thumbs-up hand filled with fill: recommended, a good review."},
  'common.pen@trace': {"label":"Shape trace","doc":"A shape line across a cut: it traces a shape on the shot before the cut (from, points as fractions of the frame), carries over the cut at cut seconds, morphs onto the same shape in the next shot (to) within morph seconds and flashes as it locks on (style, x, y, w and h are not used): match cuts, shape relays."},
  'common.emoji@sticker': {"label":"Sticker","doc":"One big emoji sticker popping up at (x, y) and wobbling: a reaction, a punchline."},
  'common.emoji@rain': {"label":"Emoji rain","doc":"A rain of emoji falling from the top, full frame (check does not count it as leaving the safe zone), count is how many: celebration, foodie vibes."},
  'common.emoji@float': {"label":"Floating","doc":"A stream of hearts and emoji rising from x, y and swaying, rate a second: a live stream's or social app's reactions."},
  'common.emoji@tap': {"label":"Double-tap heart","doc":"A double-tap's big heart popping at x, y with a ring of small hearts bursting out, then floating up and fading: a like."},
  'common.emoji@cover': {"label":"Face cover","doc":"A big emoji hiding a face: full size, opaque and still from the first frame to the last; with follow: face it grows on its own to cover from the chin to the hairline, path moves it along \"seconds|x|y|size\" lines, box draws it only inside a box (the video window of a magazine page), backing puts a disc of one colour behind it to fill the gaps between petals: someone who stays off camera."},
  'common.callout@circle': {"label":"Circle","doc":"A hand-drawn circle round the target (in color): pointing out an ingredient, the one thing to look at."},
  'common.callout@cross': {"label":"Cross","doc":"A big X over the target (in bad): don't, the wrong way."},
  'common.callout@ban': {"label":"No sign","doc":"A prohibition icon: a circle with a slash (in bad), with a phone (icon phone) or any emoji inside: something you can't do, like \"no phone orders\"."},
  'common.callout@burst': {"label":"Juice rays","doc":"Juice-squirt rays bursting outward round the target (in color): the juicy bite."},
  'common.touch@dot': {"label":"Gray dot","doc":"The phone system's translucent gray dot (edge is its outline): screen recordings of using a phone."},
  'common.touch@glow': {"label":"Glowing fingertip","doc":"A glowing white fingertip: screen recordings where the finger should stand out more."},
  'common.touch@cursor': {"label":"Mouse pointer","doc":"A computer's arrow pointer, always on screen, gliding between gestures; a tap is a click: the pointer shrinks and a ring pops out; color is the fill, edge the outline: goes with common.desktop's retro desktop."},
  'common.sticker@heart': {"label":"Heart","doc":"A plump heart sticker (color fills it): beside something loved or recommended."},
  'common.sticker@bolt': {"label":"Bolt","doc":"A slanted lightning bolt sticker: a key point, a surprise, a punchy title."},
  'common.sticker@star': {"label":"Star","doc":"A five-pointed star sticker: a highlight, the favourite on a list."},
  'common.sticker@smile': {"label":"Smiley","doc":"A round smiley sticker with blush and a curved mouth: happy, easy-going vlogs."},
  'common.panel@panel': {"label":"Thick frame","doc":"A thick frame (rounded corners, hard shadow, taped on at an angle): border is its colour, shadow the hard shadow's offset, tapeColor the tape; the default frame of c.panel()'s panel layout, for a hook short with the footage shrunk onto a patterned backdrop."},
  'common.panel@print': {"label":"Photo print","doc":"A white photo-paper border with a soft shadow and two strips of washi tape on top: margin is the border's width, print the paper colour, tapeColor2 the second tape; planners, recipes."},
  'common.panel@bezel': {"label":"Dark bezel","doc":"A narrow dark frame with a very deep soft shadow, like a screen set into a machine or sign; border is its colour."},
  'common.panel@hole': {"label":"Dark surround","doc":"Fills everything outside the frame with a dark ground (fill; faint light, fine diagonal lines) and draws a ring-coloured line around the frame edge: signboard layouts, queue displays."},
  'common.panel@offset': {"label":"Offset block","doc":"No frame: a shifted block of colour (block, offset to the lower right by shadow) behind the video window slides out from behind it at the start, like a misprinted plate: quote posters, interviews."},
  'common.panel@drawn': {"label":"Hand-drawn","doc":"A hand-drawn frame: pen picks crayon / marker / pencil / ballpoint, it is drawn stroke by stroke within drawIn seconds at the start, the line wobbles boil times per second, with a thin ring-coloured line outside (double) and tape stickers at the corners (corners): picture books, notebooks, doodle style."},
  'common.camcorder@osd': {"label":"Viewfinder OSD","doc":"The viewfinder's display over the footage: ● REC at the top left (blinking every second) / STBY / STOP / PLAY / PAUSE / FF / REW / PHOTO (status \"seconds|state\" one per line), corner marks (popping in at popAt) and a centre cross, the tape counter (counter \"seconds|reading\" sets it, then it runs with the state: 1× while recording, spin× in ff / rew, held otherwise; counterAt top puts it at the top right, bottom at the bottom left), TAPE number (tape \"seconds|number\", a tracking band at each change), battery (battery \"seconds|bars\", 0 blinks red), tape left (remain \"seconds|minutes\", under 1 minute blinks red), a date stamp (date \"seconds[-seconds]|2004-08-14 10:30[|to date or rate]\", laid out by dateFormat), a place typed in (place \"seconds-seconds|words\"; placeAt top puts it at the top left under REC, bottom at the bottom left), the W–T zoom bar (zoom \"seconds-seconds|from|to\"), TAPE END (end \"seconds-seconds\"): laid over the shots all the way, as if seen through the camcorder."},
  'common.camcorder@ff': {"label":"Fast-forward","doc":"Fast-forward: snow, then a blue screen with ▶▶ and the date rolling in big letters from `from` to `to`, then snow (snowIn and snowOut are the snow's seconds at either end, ffFormat lays out the big date, blue is the blue): skipping ahead, a few days later, say."},
  'common.camcorder@rew': {"label":"Rewind","doc":"The rewind: the stills of stills \"source|seconds|x,y,zoom\" flashing past backwards, faster and faster, torn, ◀◀ in the middle (painted stand-ins without footage): going back to an earlier shot, a recap."},
  'common.camcorder@snow': {"label":"Snow","doc":"Snow only, filling the frame: a tape change, the blank between two recordings."},
  'common.magazine@feature': {"label":"Inside page","doc":"An inside page: still cells under the window pushing in slowly (cells \"source|seconds|x,y,zoom\", - is a painted stand-in), tags on the cells (tags \"seconds|cell|EN|text\"), a red kicker chip and a big white headline over the window's top left (settling smaller at settleAt), a pull quote over a cell (quote + quoteAt; slam drops it in hard, quoteEn a small English line, quoteBy who said it), the foot line: the body of a feature, with headlines and a line pulled out as it plays."},
  'common.magazine@cover': {"label":"Cover","doc":"A cover: a huge italic masthead, the window bleeding to the edges, a red banner headline sliding in (banner / bannerEn), cover lines on the cells below (lines), a barcode: the opening, what this issue is about."},
  'common.magazine@list': {"label":"List page","doc":"A list page: the window on top, the kicker and headline on the paper and numbered rows coming in one by one (items \"seconds|title|note\"): contents, rankings."},
  'common.magazine@back': {"label":"Back cover","doc":"A back cover: the footage full page under a dark wash, the masthead, a closing line (headline / deck) and a red play button (cta): the ending, telling viewers where the full film is."},
  'common.comic@one': {"label":"One panel","doc":"One big panel for the whole page: a big moment carried by one shot, with focus lines (focus)."},
  'common.comic@two': {"label":"Two stacked","doc":"Two panels stacked, the gutter between them rising to the right: two shots, an action and its answer, a cause and its result."},
  'common.comic@two-flip': {"label":"Two, flipped","doc":"Two panels stacked, the gutter slanting the other way from two (falling to the right): after a two page, so the slants of pages in a row do not repeat."},
  'common.comic@three': {"label":"One over two","doc":"A big panel on top and two small ones side by side below, every gutter a little slanted: a main shot with two reactions or details."},
  'common.comic@four': {"label":"Four panels","doc":"Four panels, 2×2, the gutters a little slanted: a story in four beats, a string of reactions."},
  'common.comic@side': {"label":"Side by side","doc":"Two panels side by side with a slanted gutter between them: for wide films."},
  'common.grid@two': {"label":"Two stacked","doc":"Two cells, one over the other (side by side on a wide film): before and after, two places compared."},
  'common.grid@three': {"label":"One over two","doc":"A big cell on top and two small ones side by side below: a main shot with two details."},
  'common.grid@four': {"label":"Four","doc":"Four cells, 2×2: a round-up of four places or four things."},
  'common.grid@bento': {"label":"Bento","doc":"A big cell, two small ones and a strip: the big one on top, two small ones in the middle, a wide strip at the bottom; a round-up with one lead and a few details."},
  'common.grid@six': {"label":"Six","doc":"Six cells, 2×3 (3×2 on a wide film): lists, several places at once."},
  'common.flatlay@postcard': {"label":"Postcard","doc":"A landscape postcard with a white strip under the photo, the place in italics on the left (place) and the year on the right (year); turned over (flipAt), its back has a dividing line, address lines and a stamp, the handwriting (back) is written one character at a time, then the postmark lands (mark, at markAt); portrait in objects stands it upright: travel, places you have been, a line to someone."},
  'common.flatlay@polaroid': {"label":"Polaroid","doc":"A white instant photo with one handwritten line on its wide bottom border (caption): memories, that summer, birthdays."},
  'common.flatlay@photo': {"label":"Photo frame","doc":"An upright wooden frame with some depth, a white mat round the photo and one handwritten line on the mat under it (caption): old photos, remembering a year."},
  'common.flatlay@tv': {"label":"Old TV","doc":"An old TV in a wood-grain case, a 4:3 screen on the left playing the shot, two knobs and a speaker grille on the right, the brand printed under the screen (caption): nostalgia, old home videos and shows."},
  'common.flatlay@card': {"label":"Card","doc":"An upright paper card, the photo on its upper part and a wide blank below with one handwritten line (caption): birthdays, wishes, goodbyes."},
  'common.paper@desk': {"label":"Kraft desk","doc":"A kraft-paper desk (fibers, specks, vignette; the default), with an optional slightly tilted ruled index card (red top line, blue rules, washi tape), small pencil doodles and one italic signature line: recipes, planners, handwritten tutorials; neither doodles nor signature by default: doodles: true draws doodleSet's doodles: kitchen (coffee beans, a whisk: recipes), journal (stars, a heart, a spiral) or travel (a paper plane, a dashed trail, a little sun); doodles: false leaves them out; sign writes the signature, for example \"Recipe\", empty = none."},
  'common.paper@book': {"label":"Picture book","doc":"A picture-book page: mottled paper grain, spine shadow and stitching at the left, page thickness at the right, vignette, a crayon meadow strip at the bottom: picture books, storytelling; paper is the page colour, meadow the strip."},
  'common.paper@grid': {"label":"Grid notebook","doc":"A grid notebook: squares, a red margin line, binding coils along the top, vignette: notebooks, handwritten tutorials; cell is the squares, binding the coils."},
  'common.paper@print': {"label":"Magazine stock","doc":"Magazine stock: smooth off-white with fine specks, faint fibres and a warm vignette: magazine-style layouts, the paper of common.magazine."},
  'common.meter@center': {"label":"Centred number","doc":"A centred big number with the current stage name and a ruler under it (stages are the stages, stagePrefix the words before a stage name, ruler off drops the ruler, ticks are its marks): depth, altitude, temperature, a count, values that keep going up or down."},
  'common.meter@band': {"label":"Year ruler","doc":"A dark band across the top, the number flush left with a smaller unit, a ruler from min to max with numbered ticks and a marker sliding along it, flags planted at values by pins (accent in the main color, hl in the highlight color, dashed a hollow flag on a dashed pole), and when the number reaches a flag its label appears beside it: years, history, eras."},
  'common.meter@ruler': {"label":"Upright ruler","doc":"An upright ruler at the right edge: every value reached leaves an arrow with its number, the newest one big in the main color, and a pin at the same value adds its label: height, altitude, ranks."},
  'common.chart@bars': {"label":"Bars","doc":"Bars growing out with numbers jumping up (dir h horizontal / v vertical bars; compare ratio shows a \"× 6.7\" multiple, gap shows a gap bracket; base a dashed baseline; stat one line of a big number jumping up): comparing two or three numbers."},
  'common.chart@pie': {"label":"Pie","doc":"A pie painted slice by slice (note hangs a label below, colors gives the slices' colours): how a whole, such as time or money, is split."},
  'common.chart@people': {"label":"People","doc":"A row of little figures flipping one by one, the first k coloured and circled (4 out of 10 people; n is the total, and a blank stat writes \"K out of N people\"): a share of people."},
  'common.chart@rank': {"label":"Ranking","doc":"A ranking list with one row lit and tagged \"No. 12\" (the third column of data is the place; reveal up reveals it from the last place up, tied places together and the winner last; rows sharing a place get a bracket marked with tie): leaderboards, revealing places."},
  'common.chart@balance': {"label":"Scale","doc":"A scale whose weights drop into the two pans as it tips toward the heavier side (note is the words above it, tag the pans' colour): weighing two things against each other."},
  'common.chart@table': {"label":"Table","doc":"A comparison table, its lines drawn and its cells floating up along the diagonal (data is one row a line \"cell|cell|cell\", the first the header; hl is \"row,column\"): comparing a few shops or things point by point."},
  'common.chart@line': {"label":"Line","doc":"One or two curves drawn over time with a playhead, markers on the curve and a baseline (data is one curve a line \"name|1,3,2,5\", axis the two ends of the x axis, marks the markers, base the baseline, grow the playhead's time for the whole run): change over time, trends."},
  'common.audiogram@bars': {"label":"Mirrored bars","doc":"A row of mirrored bars (now in the middle, the last second spreading outwards), the cover in a rounded square above them cut to a square, count the number of bars (41 by default): talks and interviews, the name tag above the bars."},
  'common.audiogram@wave': {"label":"Flowing wave","doc":"A smooth curve of the last 1.5 s flowing from right to left, the cover in a rounded square above it cut to a square: a podcast that wants something softer than bars."},
  'common.audiogram@ring': {"label":"Round cover","doc":"A round cover with a ring of bars round it (the cover swells a little with the voice), the cover in the centre cut to a circle, count the number of bars (72 by default): when there is a show cover or a speaker's photo to put in the middle."},
  'common.candles@chart': {"label":"Chart","doc":"A glowing candlestick chart on black whose camera follows the newest bar to the right while the price range (log scale) zooms with it, taking the whole frame, with red and cyan ghosts and a zoom punch on shocks: the main picture of the film; it also has band the chart's top and bottom edges (frame-height fractions \"0.55,0.86\"), tipX where the newest bar sits; sparks spark spans (one \"s-s\" a line); markers (one \"s-s|date|words\" a line: a gold dot with words); refs dashed reference lines (one \"s-s|date|words\" a line: an old high); brackets measuring brackets (one \"s-s|start date\" a line, labelled with the change); crashes \"peak date|low date\" with glow spans lighting them up and dimming the rest; bolts lightning seconds (\"second@date\" strikes that day); bursts fireworks; grays turns black and white (a day the market closed); reds a red alert (vignette + virus specks); hud an alert frame (one \"s-s|words\" a line); pillars white light pillars (one \"s-s|date\" a line); walls walls of stock tiles (one \"s-s|start date|title\" a line; the stocks come from wall, a wide CSV \"date,AAPL:Apple,MSFT:Microsoft,…\" with each stock's close, the first 12 taken, a tilted 3D wall whose tiles show each stock's change from the start to the day the chart has reached)."},
  'common.candles@header': {"label":"Header","doc":"The small label (label), the close as a big ticking number (red or green by the last 20 bars), the date, and a chip on the right: the fall from the high (vs) or the new-high word (high), with the old high's date (prev) once the fall passes 5%; above the chart, given the same keys, it tells the price at that moment."},
  'common.candles@tally': {"label":"Crash tally","doc":"A row of squares counting the crashes (falls, one a line \"peak date|date it fell through the threshold|date it recovered\": a square turns the fall colour when it falls through and the rise colour with a check when it recovers, \"n/total\" on the right, tallyLabel on the left, from the film second it starts counting): a crash retrospective, how many and how many recovered."},
  'common.candles@card': {"label":"Event card","doc":"A coloured bar on the left (color), a tag chip (tag) and a date (date), a bold title (title) and a line under it (sub), sliding in with a glitchy title: what happened on the day the chart has reached (a financial crisis, a bank collapsing)."},
  'common.candles@big': {"label":"Big word","doc":"One big word (text: numbers and percentages count up from 0; tone up rise colour / down fall colour / white / gold, font num narrow figures / text heavy sans, size, align left / center) with a line under it (sub): a number to take in at a glance, such as a one-day fall."},
  'common.list@check': {"label":"Ticks","doc":"A tick in a round chip (the good colour) before each line: three key points, things to remember."},
  'common.list@pros': {"label":"Pros and cons","doc":"+ pro / − con before each line, an item starting with - counting as a con (pros in the good colour, cons in accent): the pros and cons of a review."},
  'common.list@number': {"label":"Numbered","doc":"A round chip numbered 1. 2. 3. before each line: tutorial steps, things done in order."},
  'common.notecard@step': {"label":"Step card","doc":"A red-pen circled number (no), a title, one or two lines of explanation (text) and \"label|content\" fields (fields): one step of a recipe or tutorial."},
  'common.notecard@list': {"label":"Checklist","doc":"Check boxes ticked item by item; size enlarges the list's words, and with many items or big words they go in one or two columns and the card grows taller; tick makes a to-do list being ticked off: the list is already written, the card slides in from the left, the items before item tick are ticked and highlighted, item tick is ticked now with a highlighter stroke, and the card slides out again; ticked names the items already done, strike crosses a ticked item out in red pen, stamp lands a red rubber stamp once every item is ticked, check off only writes the list, out off keeps the card on screen, addInk writes the items starting with + (added later) in another ink: ingredient lists, to-do lists."},
  'common.notecard@title': {"label":"Dish name","doc":"A big dish name with a red underline, a subtitle (sub) and a foreign name (latin): naming the dish at the start of a recipe."},
  'common.notecard@done': {"label":"Done card","doc":"\"Done!\" plus a hand-drawn heart (sub is the dish, latin its foreign name, note a small last line): the end, once it is made."},
  'common.versus@title': {"label":"Face-off opener","doc":"A big word slamming into each of the top and bottom panes (words, He said / She said), a VS diamond spinning in on the caption band in the middle and the names (names) at the sides: the opening; give dir, top, band and foot as for common.duo."},
  'common.versus@round': {"label":"Round card","doc":"A full-frame round card: the two sides' colors slide in from both edges and collide diagonally, ROUND 1 (label) pops out, the question (text) floats up (a 【word】 turns yellow) and finally it is pulled away upward: the start of each question or round."},
  'common.versus@table': {"label":"Comparison table","doc":"A comparison table: \"a vs b\", two columns of names, one question per row (rows: question|what a said|what b said|a tag|b tag, \\n for a line break) sliding in row by row, ending with a last question to the audience (ask): the close."},
  'common.story@poll': {"label":"Poll","doc":"A white sticker with a question and two to four answer bars, each filling to its result as the vote comes in, the percentages counting up, a tick on the chosen one: asking viewers a yes-or-no or which-one question (shall we go again?); the question is text, options are separated by |, the vote comes in at at, votes are the results (e.g. 62,38) and pick gets the tick."},
  'common.story@slider': {"label":"Emoji slider","doc":"A white sticker with a track under the question, an emoji sliding to value (0–1) between at and end: letting viewers rate something or show how much they like it (how blue is this sea?); emoji is the face on the slider."},
  'common.story@timer': {"label":"Timer","doc":"A dark sticker whose mm:ss runs from from seconds to to seconds between at and end: waiting or counting down (waiting for the food); icon is a built-in glyph or an emoji, text the small words above the time."},
  'common.album@grid': {"label":"Photo grid","doc":"Photo tiles in groups (each headed by its place and date, a date bubble at the right edge following along), a title and a top-right button above, the tab bar below: browsing the album, looking back on a trip a day at a time; \"# place|date|bubble words|layout\" starts a group (no place = the date alone; layout L big left and two small, R mirrored, 2 side by side, 1 full width, 3 rows of three, empty = by the count, threes alternating L / R; the rest in rows of three), scroll \"seconds|position|ease\" (position = a group from 0, fractions allowed; end = the bottom; 850px in px; ease out / inOut / linear / back), the date bubble is bubble (the date and bubble words), hide \"s-s|photo\" blanks the tile flying open, the title (empty = the lit tab's name) and the button (button), the tab bar (tabs \"icon|name\" comma separated, tab the lit one, -1 = the first on grid, the second on foryou), optional segmented chips (chips, chip)."},
  'common.album@foryou': {"label":"Memories page","doc":"The memories page: a title, a section heading with a more link, one big memory card (cardTitle in handwriting, cardSub), the next row's title (next) peeking in, the same tab bar as grid: opening a memory, then zoom flies from the card into the film; the card's picture is source / t / crop (empty = photo pick), it gives a little at tapAt, and fadeIn fades it in from the paper colour."},
  'common.album@zoom': {"label":"Tap-open flight","doc":"A picture flying from zoomFrom to zoomTo (tile: tile pick, at the scroll position of the item start; full: the whole screen with crop as the main-track clip, so the real clip takes over; fit: the whole picture letterboxed; card: the memory card), the black behind it following (full = black): opening a photo from the album into the real clip, or shrinking from the clip back into the album; move seconds for the flight (ease), fadeOut at the end."},
  'common.album@swipe': {"label":"Swipe","doc":"The viewer going left: this one (source or photo pick) leaves, the next (source2 or photo pick + 1) comes in from the right: leafing through photos one after another; fit / fit2 show a whole picture (letterboxed)."},
  'common.album@viewer': {"label":"Photo viewer","doc":"The bars round a picture: back, date, when, the action word, the toolbar (tools: icons comma separated), the main-track clip showing between them: looking at one photo on the phone and liking it; heart pops and turns the heart colour at heartAt, show \"seconds|opacity\" keys (fade them once a clip plays)."},
  'common.search@home': {"label":"Home","doc":"The start page over the main-track clip, blurred and darkened: a headline, the query typed into the box, an autocomplete list dropping below: opening on what to look up (where to go this weekend?); the hint headline, query the box's words, the autocomplete list sugg one row per line (\"prefix|completion\" or the whole row; the part that is the query is light, the rest bold), pick which row is tapped at pickAt and the box then holds it, out seconds sliding away."},
  'common.search@results': {"label":"Results","doc":"The results page: the box, a tab bar, a title and snippet, a rounded video window in the middle, fact cards popping from its lower left: introducing a place or a subject, its points on a few fact cards; the box types, erase deleting the old words first; tabs \"All, News…\" with the underline sliding from tabFrom to tab; title, titleSub, snip; the video window is a rounded hole, the main-track clip takes frame: searchWindow(params, width, height); a loading card until load; facts one card per line \"seconds|label|big|unit\" popping from the window's lower left; dym did you mean (dymAt, dymHi the letter marked, dymLead the words before it); big a big word over the window; related \"a, b; c\"; press the box lights up as search is pressed; view full = the clip fills the screen with the box, tabs and chips one per line \"seconds|word\" lighting up in turn floating at the top."},
  'common.search@ask': {"label":"Questions","doc":"Questions opening: a list of questions, each opening into the video window, the list scrolling up a row as it closes: answering common questions one by one, an answer kept for the full version if you like; qs one per line \"s-s|question|hint\", hint redact = the answer hidden plus reveal."},
  'common.search@end': {"label":"Ending","doc":"The ending: the box typed again and a suggestion picked, then a featured snippet with the answer redacted and a result card whose thumbnail is the video window: sending viewers to the full version at the end; snipAt the snippet (snipTitle, snipLead, snipNote), cardAt the result card (badge, title, dur), the play button pressed at press."},
  'common.search@bar': {"label":"Search pill","doc":"No page: a small search pill pinned near the top over the footage (a magnifier and the query), a check popping on at its right end at press: staying on while the speaker answers that question; typeAt -1 = already in the box, barY its centre height (-1 = under the top safe line), and it fades out over the last out seconds, 0.3 s unless set."},
  'common.window@media': {"label":"Clip or photo","doc":"The window plays its own clip or photo: showing a photo or a short clip (a party picture); source, in; cx, cy, zoom frame it; with progTo a progress bar sits under the picture."},
  'common.window@search': {"label":"Search box","doc":"A search box in the window typing text out letter by letter: typing a keyword that leads into the next part (today's birthday star); typeAt starts the typing."},
  'common.window@profile': {"label":"Profile list","doc":"\"name|value\" rows appearing one by one in the window: introducing a person (name, age, status); text has one row per line."},
  'common.window@progress': {"label":"Progress bar","doc":"A progress bar filling in the window, the words above it changing from doing to done: something getting ready and done (decorating, then done); text \"doing|done\", full from progFrom to progTo."},
  'common.outro@cta': {"label":"Funnel card","doc":"An end card that leads viewers on: paper-colored ground, several lines of big text stamped down one by one on the beat, a row of numbered dots below (the last few with question marks), and a hand-drawn arrow drawn toward the link and bouncing on the beats: pointing to the original film, the profile, comments, the next episode; cta is the small words by the arrow, tipX, tipY the arrow's tip, dots the number of dots and hidden how many get question marks."},
  'common.outro@credits': {"label":"Credits","doc":"Closing thank-you credits: the lines fade up one a beat (*lines in stars* italic in the highlight color with Chinese, Japanese and Korean characters upright, _lines in underscores_ small and letter-spaced, the rest bold names) over a soft dark veil: the end of a birthday, wedding or graduation film; cover sets how dark the veil is, y is the list centre, and the opening name title is common.headline look name."},
  'common.outro@episode': {"label":"Show end card","doc":"On the ink colour (cover sets how solid), the show's name in big serif lines over an accent rule, a rounded 16:9 window with a play button in the middle (a hole: the main-track clip's frame is outroWindow(params, W, H)), then the episode line (ep), an accent button (cta) and a small credit line (credit), rising in one after another: a show's end card (a podcast, an interview, a series); y is the centre of the whole stack."},
  'common.echo@stack': {"label":"Stacked","doc":"Outlined copies stacked echoes deep above and below the word, spreading out from it at the start, fainter outward: the default echo word, for place names, action words, chapter openers."},
  'common.echo@trail': {"label":"Trail","doc":"Outlined copies behind the word, each a step further down and to the right and fainter, sliding out from under it at the start like a solid depth trail: dashing off, speed, a title with weight; echoes is how many in all."},
  'common.echo@zoom': {"label":"Ripple","doc":"Outlined copies on the word's centre, each larger (about 1.25, 1.55, 1.9 times) and fainter, pushed outward at the start and then breathing slowly, a ripple round the word: a beat, a shock, a heartbeat, look at this word; echoes is how many in all."},
  'common.echo@wave': {"label":"Wave","doc":"The stacked outlined copies swaying sideways, each layer a beat behind the one before, a wave travelling outward while the solid word holds still: music, the sea, swaying, an easy stretch; echoes is how many above and below."},
  'common.band@tape': {"label":"Tape","doc":"A solid band in color with words in ink scrolling left, wiped in from the left: the default beat-word tape."},
  'common.band@caution': {"label":"Caution tape","doc":"A slightly wider hazard tape: color with a row of diagonal ink stripes along its top and bottom edges, moving with the words between them: under construction, warning, danger, limited time, big news."},
  'common.band@cross': {"label":"Cross","doc":"Two bands crossing in an X: the second at the opposite angle with its colours swapped (ink band, color words), its words scrolling right, wiped in from the right a moment later: blocked off, forbidden, a clash, two things colliding, a lively opener."},
  'common.band@outline': {"label":"Outline","doc":"No fill: two thin lines in color along the band's edges with the words in color between them, letting more of the picture through: a beautiful shot you do not want to cover, lighter beat words; ink is unused."},
  'combo:impact': {"label":"Impact","doc":"A punch, a slap, a landing, a big word slammed in: lines burst from the middle as a glow flares there and shrinks back, with a heavy hit and the clip shaking."},
  'combo:glitchcut': {"label":"Glitch cut","doc":"A sudden change of topic, something going wrong, a jump to another scene: scan lines and a sideways jump across the cut, then the colours split, with a record scratch."},
  'combo:punchline': {"label":"Punchline","doc":"A joke landing, a comeback, a deadpan stare: the picture turns into comic-book halftone dots as thick black focus lines close in from the edges, with a cartoon spring boing and a small shake."},
  'combo:rewind': {"label":"Rewind","doc":"Going back to look again, back to a moment ago, once more: the picture turns into a videotape, a tracking band slides down and a few inverted strips flicker across, with the whirr of a tape rewinding."},
  'combo:reveal': {"label":"Reveal","doc":"The answer revealed, the finished thing shown, a product's entrance: a rainbow band sweeps the frame from the left and, as it crosses the middle, a bright point flares into a big four-way glint, with a bright shing."},
  'combo:celebrate': {"label":"Celebrate","doc":"A goal reached, a level cleared, an award, a birthday: a soft golden glow lights up just above the middle and slowly fades (no flash) while coloured confetti rains down from the top, with an 8-bit victory fanfare."},
  'combo:leader': {"label":"Film leader","doc":"The film starts, a nostalgic opening: a projected home movie, the old leader's big disc counting down from 3 to 1 with its hand sweeping a turn a second, a tick on each count and a beep at the end."},
  'combo:memory': {"label":"Memory","doc":"A memory, the old days, thinking back: a warm light rises in the top left corner and fades again while coarse film grain covers the frame, with a soft chime."},
  'combo:rush': {"label":"Rush","doc":"Speeding up, hurrying, fast-forward, a dash: white speed lines fly to the right across the frame as a small bright light sweeps from the left, with a whoosh, a rising fast-forward and a small shake."},
  'combo:closing': {"label":"Closing time","doc":"For the very end of the film only (its last 2.4 seconds, ending with the film; placed in the middle, the footage comes back after 2.4 seconds). Done for the day, closed, that's all for today: a roller shutter rattles down over the whole frame, lands with a clunk and gets a closed sign taped on, then everything fades to black."},
  'combo:irisout': {"label":"Iris out","doc":"An old-cartoon ending or scene change: the picture closes to a circle and down to a point in the middle, a handful of stars bursts from that point, and it opens from there onto the next shot, with a xylophone plink."},
  'combo:stage': {"label":"Entrance","doc":"The star walks on, an announcement, an award: out-of-focus stage lights come up with a rising sound, and at the moment a very bright lens flare streak hits the top of the frame, with a heavy hit."},
};
